def get_file_contents(connection_id, repo_full_name, path, ref=None, **_extra):
    import json, os, datetime, re, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0069000" if __import__("os").path.isdir("./environment_mix/0069000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex[:24].upper()}"

    def _choose_connection(req_connection_id):
        conns = _load("github_connections.json")
        if not (isinstance(req_connection_id, str) and re.fullmatch(r"^ghc_[0-9A-Z]{18,}$", req_connection_id or "") is not None):
            return None
        for c in conns:
            if isinstance(c, dict) and c.get("id") == req_connection_id and c.get("status") == "active":
                return c
        return None

    def _log_call(tool_name, conn_id, request_obj, resolved_repo_full_name=None, repo_id=None):
        calls = _load("github_tool_calls.json")
        cid = _new_id("gtc")
        now = _now()
        row = {
            "id": cid,
            "connection_id": conn_id,
            "tool_name": tool_name,
            "request_json": request_obj if isinstance(request_obj, dict) else {},
            "resolved_repo_full_name": resolved_repo_full_name,
            "repo_id": repo_id,
            "issue_pr_id": None,
            "http_status": None,
            "rate_limit_remaining": None,
            "rate_limit_reset_at": None,
            "status": "queued",
            "error_code": None,
            "error_message": None,
            "response_json": None,
            "started_at": None,
            "finished_at": None,
            "created_at": now,
            "updated_at": now,
        }
        calls.append(row)
        _save("github_tool_calls.json", calls)
        now2 = _now()
        for r in calls:
            if isinstance(r, dict) and r.get("id") == cid:
                r["status"] = "running"
                r["started_at"] = r.get("started_at") or now2
                r["updated_at"] = now2
                break
        _save("github_tool_calls.json", calls)
        return cid

    def _finish_call(call_id, status, http_status=None, response_json=None, error_code=None, error_message=None, repo_id=None):
        calls = _load("github_tool_calls.json")
        finished = _now()
        allowed = {"queued": {"running", "failed"}, "running": {"succeeded", "failed"}, "succeeded": set(), "failed": set()}
        for r in calls:
            if isinstance(r, dict) and r.get("id") == call_id:
                cur = r.get("status")
                if cur in allowed and status in allowed[cur]:
                    r["status"] = status
                else:
                    r["status"] = status
                r["http_status"] = http_status
                r["response_json"] = response_json
                r["error_code"] = error_code
                r["error_message"] = error_message
                if repo_id is not None:
                    r["repo_id"] = repo_id
                r["finished_at"] = finished
                r["updated_at"] = finished
                break
        _save("github_tool_calls.json", calls)

    # Validate
    if not (isinstance(connection_id, str) and re.fullmatch(r"^ghc_[0-9A-Z]{18,}$", connection_id) is not None):
        return _err("VALIDATION_ERROR", "Invalid connection_id.")
    if not (isinstance(repo_full_name, str) and "/" in repo_full_name and len(repo_full_name.split("/", 1)[0]) > 0 and len(repo_full_name.split("/", 1)[1]) > 0):
        return _err("VALIDATION_ERROR", "repo_full_name must be in 'owner/name' form.", repo_full_name=repo_full_name)
    if not isinstance(path, str) or path.strip() == "":
        return _err("VALIDATION_ERROR", "path must be a non-empty string.")
    if ref is not None and (not isinstance(ref, str) or ref.strip() == ""):
        return _err("VALIDATION_ERROR", "ref must be a non-empty string when provided.")

    conn = _choose_connection(connection_id)
    if not conn:
        return _err("UNAUTHORIZED", "Invalid or inactive connection_id.", connection_id=connection_id)

    repos = _load("github_repositories.json")
    repo = None
    for r in repos:
        if isinstance(r, dict) and r.get("full_name") == repo_full_name and r.get("status") != "deleted":
            repo = r
            break

    call_id = _log_call(
        "get_file_contents",
        conn.get("id"),
        {"connection_id": connection_id, "repo_full_name": repo_full_name, "path": path, "ref": ref},
        resolved_repo_full_name=repo_full_name,
        repo_id=repo.get("id") if repo else None,
    )

    if repo is None:
        _finish_call(call_id, "failed", http_status=404, error_code="github_404", error_message="Repository not found.")
        return _err("NOT_FOUND", "Repository not found.", repo_full_name=repo_full_name)

    gitobjs = _load("github_git_objects.json")

    # If path looks like directory, return listing of direct children based on stored blobs/trees
    is_dir = path.endswith("/") or any(isinstance(o, dict) and o.get("repo_id") == repo.get("id") and o.get("path") and str(o.get("path")).startswith(path.rstrip("/") + "/") for o in gitobjs)
    if is_dir:
        prefix = path.rstrip("/") + "/"
        entries = {}
        for o in gitobjs:
            if not isinstance(o, dict):
                continue
            if o.get("repo_id") != repo.get("id"):
                continue
            if o.get("object_type") not in ("blob", "tree"):
                continue
            p = o.get("path")
            if not isinstance(p, str) or not p.startswith(prefix):
                continue
            rest = p[len(prefix):]
            if rest == "":
                continue
            name = rest.split("/", 1)[0]
            if name not in entries:
                entries[name] = {"name": name, "path": prefix + name, "type": "dir" if "/" in rest else "file"}
        listing = sorted(entries.values(), key=lambda x: (x["type"] != "dir", x["name"]))
        resp = {
            "type": "dir",
            "repository": {"id": repo.get("id"), "full_name": repo.get("full_name")},
            "ref": ref or repo.get("default_branch"),
            "path": path,
            "entries": listing,
        }
        _finish_call(call_id, "succeeded", http_status=200, response_json=resp, repo_id=repo.get("id"))
        return resp

    # File: find blob at exact path
    blob = None
    for o in gitobjs:
        if isinstance(o, dict) and o.get("repo_id") == repo.get("id") and o.get("object_type") == "blob" and o.get("path") == path and o.get("status") != "tombstoned":
            blob = o
            break

    if blob is None:
        _finish_call(call_id, "failed", http_status=404, error_code="github_404", error_message="Path not found.")
        return _err("NOT_FOUND", "Path not found.", repo_full_name=repo_full_name, path=path)

    # Enforce size constraint when returning content
    size_bytes = blob.get("size_bytes")
    if isinstance(size_bytes, int) and size_bytes > 10485760:
        _finish_call(call_id, "failed", http_status=413, error_code="validation_error", error_message="Stored content exceeds 10MB.")
        return _err("VALIDATION_ERROR", "Stored content exceeds 10MB.", size_bytes=size_bytes)

    resp = {
        "type": "file",
        "repository": {"id": repo.get("id"), "full_name": repo.get("full_name")},
        "ref": ref or repo.get("default_branch"),
        "path": path,
        "sha": blob.get("sha"),
        "encoding": blob.get("encoding") if blob.get("encoding") in ("base64", "utf-8", "none") else blob.get("encoding"),
        "content_text": blob.get("content_text"),
        "content_bytes_b64": blob.get("content_bytes_b64"),
        "size_bytes": blob.get("size_bytes"),
        "last_fetched_at": blob.get("last_fetched_at"),
    }
    _finish_call(call_id, "succeeded", http_status=200, response_json=resp, repo_id=repo.get("id"))
    return resp

def push_files(connection_id, repo_full_name, branch, message, files, **_extra):
    import json, os, datetime, re, base64, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0069000" if __import__("os").path.isdir("./environment_mix/0069000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _gen_id(prefix):
        return f"{prefix}_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S%f')}_{os.urandom(4).hex()}"

    def _sha_from_bytes(b):
        return hashlib.sha1(b).hexdigest()

    def _record_tool_call(tool_calls, connection_id, tool_name, request_json, status, http_status=None,
                          resolved_repo_full_name=None, repo_id=None, issue_pr_id=None,
                          error_code=None, error_message=None, response_json=None,
                          started_at=None, finished_at=None, rate_limit_remaining=None, rate_limit_reset_at=None):
        now = _now()
        row = {
            "id": _gen_id("ghtc"),
            "connection_id": connection_id,
            "tool_name": tool_name,
            "request_json": request_json if isinstance(request_json, dict) else {},
            "resolved_repo_full_name": resolved_repo_full_name,
            "repo_id": repo_id,
            "issue_pr_id": issue_pr_id,
            "http_status": http_status,
            "rate_limit_remaining": rate_limit_remaining,
            "rate_limit_reset_at": rate_limit_reset_at,
            "status": status,
            "error_code": error_code,
            "error_message": error_message,
            "response_json": response_json,
            "started_at": started_at,
            "finished_at": finished_at,
            "created_at": now,
            "updated_at": now,
        }
        tool_calls.append(row)
        return row

    def _transition_tool_call(row, new_status, http_status=None, error_code=None, error_message=None, response_json=None):
        transitions = {
            "queued": ["running", "failed"],
            "running": ["succeeded", "failed"],
            "succeeded": [],
            "failed": [],
        }
        cur = row.get("status")
        if new_status not in transitions.get(cur, []):
            return False
        now = _now()
        if new_status == "running":
            row["started_at"] = row.get("started_at") or now
        if new_status in ("succeeded", "failed"):
            row["finished_at"] = now
        row["status"] = new_status
        row["updated_at"] = now
        if http_status is not None:
            row["http_status"] = http_status
        if error_code is not None:
            row["error_code"] = error_code
        if error_message is not None:
            row["error_message"] = error_message
        if response_json is not None:
            row["response_json"] = response_json
        return True

    started = datetime.datetime.utcnow()

    # Validate inputs
    if not isinstance(connection_id, str) or not re.match(r"^ghc_[0-9A-Z]{18,}$", connection_id):
        return _err("VALIDATION_ERROR", "Invalid connection_id.", field="connection_id")
    if not isinstance(repo_full_name, str) or "/" not in repo_full_name or repo_full_name.count("/") != 1:
        return _err("VALIDATION_ERROR", "Invalid repo_full_name; expected 'owner/name'.", field="repo_full_name")
    if not isinstance(branch, str) or not branch.strip():
        return _err("VALIDATION_ERROR", "Invalid branch.", field="branch")
    if not isinstance(message, str) or not message.strip():
        return _err("VALIDATION_ERROR", "Invalid message.", field="message")
    if not isinstance(files, list) or len(files) == 0:
        return _err("VALIDATION_ERROR", "files must be a non-empty array.", field="files")

    for i, f in enumerate(files):
        if not isinstance(f, dict):
            return _err("VALIDATION_ERROR", "Each file entry must be an object.", index=i)
        if "path" not in f or "encoding" not in f:
            return _err("VALIDATION_ERROR", "Each file entry must include path and encoding.", index=i)
        if not isinstance(f["path"], str) or not f["path"] or f["path"].startswith("/") or "\x00" in f["path"]:
            return _err("VALIDATION_ERROR", "Invalid file path.", index=i, field="path")
        if f["encoding"] not in ("utf-8", "base64"):
            return _err("VALIDATION_ERROR", "Invalid encoding; must be 'utf-8' or 'base64'.", index=i, field="encoding")
        ct = f.get("content_text")
        cb = f.get("content_bytes_b64")
        if f["encoding"] == "utf-8":
            if ct is None or not isinstance(ct, str):
                return _err("VALIDATION_ERROR", "encoding='utf-8' requires content_text (string).", index=i)
            if cb is not None:
                return _err("VALIDATION_ERROR", "content_bytes_b64 must be omitted when encoding='utf-8'.", index=i)
        if f["encoding"] == "base64":
            if cb is None or not isinstance(cb, str):
                return _err("VALIDATION_ERROR", "encoding='base64' requires content_bytes_b64 (string).", index=i)
            if ct is not None:
                return _err("VALIDATION_ERROR", "content_text must be omitted when encoding='base64'.", index=i)
        sha = f.get("sha")
        if sha is not None:
            if not isinstance(sha, str) or not re.match(r"^[0-9a-f]{7,40}$", sha):
                return _err("VALIDATION_ERROR", "Invalid sha format.", index=i, field="sha")

    # Load collections
    conns = _load("github_connections.json")
    repos = _load("github_repositories.json")
    gobs = _load("github_git_objects.json")
    tool_calls = _load("github_tool_calls.json")

    # Tool call row: queued
    tc = _record_tool_call(
        tool_calls,
        connection_id=connection_id,
        tool_name="push_files",
        request_json={"connection_id": connection_id, "repo_full_name": repo_full_name, "branch": branch, "message": message, "files": files},
        status="queued",
        resolved_repo_full_name=repo_full_name
    )
    _save("github_tool_calls.json", tool_calls)

    # Auth & prerequisites
    conn = next((c for c in conns if c.get("id") == connection_id and c.get("status") == "active"), None)
    if not conn:
        _transition_tool_call(tc, "failed", http_status=401, error_code="github_401", error_message="Unauthorized: invalid or inactive connection.")
        _save("github_tool_calls.json", tool_calls)
        return _err("UNAUTHORIZED", "Invalid or inactive connection_id.", connection_id=connection_id)

    base_repo = next((r for r in repos if r.get("full_name") == repo_full_name), None)
    if not base_repo:
        _transition_tool_call(tc, "failed", http_status=404, error_code="github_404", error_message="Repository not found in cache.")
        _save("github_tool_calls.json", tool_calls)
        return _err("NOT_FOUND", "Repository not found.", repo_full_name=repo_full_name)

    if base_repo.get("status") == "deleted":
        _transition_tool_call(tc, "failed", http_status=404, error_code="github_404", error_message="Repository deleted.")
        _save("github_tool_calls.json", tool_calls)
        return _err("NOT_FOUND", "Repository is deleted.", repo_full_name=repo_full_name)

    # Branch ref must exist (or at least be representable). We'll require an existing ref to update.
    ref_name = f"refs/heads/{branch}"
    ref_obj = next((o for o in gobs if o.get("repo_id") == base_repo["id"] and o.get("object_type") == "ref" and o.get("ref_name") == ref_name), None)
    if not ref_obj or ref_obj.get("status") == "tombstoned":
        _transition_tool_call(tc, "failed", http_status=422, error_code="validation_error", error_message="Base branch ref not found.")
        _save("github_tool_calls.json", tool_calls)
        return _err("VALIDATION_ERROR", "Branch not found.", branch=branch)

    # running
    if not _transition_tool_call(tc, "running"):
        _transition_tool_call(tc, "failed", http_status=500, error_code="invalid_transition", error_message="Tool call status transition failed.")
        _save("github_tool_calls.json", tool_calls)
        return _err("INVALID_TRANSITION", "Tool call status transition failed.")

    # Apply file ops: create/update blobs
    per_file = []
    updated_gobs = False

    # Index existing blobs by path
    existing_blobs = {}
    for o in gobs:
        if o.get("repo_id") == base_repo["id"] and o.get("object_type") == "blob" and o.get("path"):
            # Keep most recently updated for the path
            p = o.get("path")
            if p not in existing_blobs or (o.get("updated_at") or "") > (existing_blobs[p].get("updated_at") or ""):
                existing_blobs[p] = o

    max_bytes = 10 * 1024 * 1024
    now = _now()

    for f in files:
        path = f["path"]
        enc = f["encoding"]
        old = existing_blobs.get(path)

        # If updating existing, require sha and match
        if old is not None:
            if not f.get("sha"):
                _transition_tool_call(tc, "failed", http_status=422, error_code="validation_error", error_message=f"Missing sha for existing file: {path}")
                _save("github_tool_calls.json", tool_calls)
                return _err("VALIDATION_ERROR", "Updating an existing file requires sha.", path=path)
            if f.get("sha") != old.get("sha"):
                _transition_tool_call(tc, "failed", http_status=409, error_code="github_409", error_message=f"SHA mismatch for {path}")
                _save("github_tool_calls.json", tool_calls)
                return _err("CONFLICT", "sha does not match current file version.", path=path, expected_sha=old.get("sha"))

        # Decode/measure content
        if enc == "utf-8":
            b = f.get("content_text", "").encode("utf-8")
            content_text = f.get("content_text")
            content_b64 = None
            encoding_field = "utf-8"
        else:
            try:
                b = base64.b64decode(f.get("content_bytes_b64", ""), validate=True)
            except Exception:
                _transition_tool_call(tc, "failed", http_status=422, error_code="validation_error", error_message=f"Invalid base64 content for {path}")
                _save("github_tool_calls.json", tool_calls)
                return _err("VALIDATION_ERROR", "Invalid base64 content.", path=path)
            content_text = None
            content_b64 = f.get("content_bytes_b64")
            encoding_field = "base64"

        if len(b) > max_bytes:
            _transition_tool_call(tc, "failed", http_status=413, error_code="validation_error", error_message=f"File exceeds 10MB limit: {path}")
            _save("github_tool_calls.json", tool_calls)
            return _err("VALIDATION_ERROR", "File exceeds 10MB limit.", path=path, size_bytes=len(b))

        new_sha = _sha_from_bytes(b)

        # Upsert blob with unique(repo_id, object_type, sha, path, ref_name) (ref_name null for blobs)
        blob = next((o for o in gobs if o.get("repo_id") == base_repo["id"] and o.get("object_type") == "blob" and o.get("sha") == new_sha and o.get("path") == path and o.get("ref_name") is None), None)
        if blob is None:
            blob = {
                "id": _gen_id("gho"),
                "repo_id": base_repo["id"],
                "object_type": "blob",
                "ref_name": None,
                "branch_name": None,
                "sha": new_sha,
                "parent_sha_list": None,
                "author_login": None,
                "author_email": None,
                "message": None,
                "committed_at": None,
                "path": path,
                "encoding": encoding_field,
                "content_text": content_text,
                "content_bytes_b64": content_b64,
                "size_bytes": len(b),
                "status": "present",
                "last_fetched_at": now,
                "created_at": now,
                "updated_at": now,
            }
            gobs.append(blob)
            updated_gobs = True
        else:
            # refresh content and timestamps if already exists (idempotent)
            blob["encoding"] = encoding_field
            blob["content_text"] = content_text
            blob["content_bytes_b64"] = content_b64
            blob["size_bytes"] = len(b)
            if blob.get("status") == "tombstoned":
                # illegal transition: tombstoned cannot move
                _transition_tool_call(tc, "failed", http_status=409, error_code="invalid_transition", error_message=f"Blob is tombstoned: {path}")
                _save("github_tool_calls.json", tool_calls)
                return _err("INVALID_TRANSITION", "Cannot update a tombstoned blob.", path=path)
            blob["status"] = "present"
            blob["last_fetched_at"] = now
            blob["updated_at"] = now
            updated_gobs = True

        per_file.append({
            "path": path,
            "encoding": enc,
            "old_sha": old.get("sha") if old else None,
            "new_sha": new_sha,
            "updated": old is not None,
            "created": old is None
        })

    # Create commit object
    parent_sha = ref_obj.get("sha")
    commit_material = (repo_full_name + "\n" + ref_name + "\n" + (parent_sha or "") + "\n" + message + "\n" +
                       "\n".join([pf["path"] + ":" + pf["new_sha"] for pf in per_file]) + "\n" + now).encode("utf-8")
    commit_sha = _sha_from_bytes(commit_material)

    existing_commit = next((o for o in gobs if o.get("repo_id") == base_repo["id"] and o.get("object_type") == "commit" and o.get("sha") == commit_sha and o.get("path") is None and o.get("ref_name") is None), None)
    if existing_commit is None:
        commit_obj = {
            "id": _gen_id("gho"),
            "repo_id": base_repo["id"],
            "object_type": "commit",
            "ref_name": None,
            "branch_name": None,
            "sha": commit_sha,
            "parent_sha_list": [parent_sha] if parent_sha else [],
            "author_login": conn.get("github_login"),
            "author_email": None,
            "message": message,
            "committed_at": now,
            "path": None,
            "encoding": None,
            "content_text": None,
            "content_bytes_b64": None,
            "size_bytes": None,
            "status": "present",
            "last_fetched_at": now,
            "created_at": now,
            "updated_at": now,
        }
        gobs.append(commit_obj)
        updated_gobs = True
    else:
        if existing_commit.get("status") == "tombstoned":
            _transition_tool_call(tc, "failed", http_status=409, error_code="invalid_transition", error_message="Commit is tombstoned.")
            _save("github_tool_calls.json", tool_calls)
            return _err("INVALID_TRANSITION", "Cannot reuse a tombstoned commit.")
        existing_commit["updated_at"] = now
        existing_commit["last_fetched_at"] = now
        existing_commit["status"] = "present"
        updated_gobs = True

    # Advance ref to new commit sha (ref: present->stale/tombstoned only; but we can keep present and update sha)
    if ref_obj.get("status") == "tombstoned":
        _transition_tool_call(tc, "failed", http_status=409, error_code="invalid_transition", error_message="Branch ref is tombstoned.")
        _save("github_tool_calls.json", tool_calls)
        return _err("INVALID_TRANSITION", "Cannot update a tombstoned ref.", branch=branch)
    ref_obj["sha"] = commit_sha
    ref_obj["updated_at"] = now
    ref_obj["status"] = "present"
    ref_obj["last_fetched_at"] = now
    updated_gobs = True

    # Touch repo last_synced_at
    base_repo["last_synced_at"] = now
    base_repo["updated_at"] = now

    if updated_gobs:
        _save("github_git_objects.json", gobs)
        _save("github_repositories.json", repos)

    resp = {
        "repo_full_name": repo_full_name,
        "branch": branch,
        "commit": {
            "sha": commit_sha,
            "message": message,
            "parent_shas": [parent_sha] if parent_sha else [],
            "committed_at": now
        },
        "files": per_file
    }

    _transition_tool_call(tc, "succeeded", http_status=201, response_json=resp, repo_id=base_repo["id"] if isinstance(base_repo.get("id"), str) else None)
    # Note: tool_calls schema has repo_id column, but our helper doesn't accept mutation; set directly
    tc["repo_id"] = base_repo["id"]
    tc["response_json"] = resp
    tc["http_status"] = 201
    tc["updated_at"] = _now()
    tc["finished_at"] = tc.get("finished_at") or _now()
    _save("github_tool_calls.json", tool_calls)

    latency_ms = int((datetime.datetime.utcnow() - started).total_seconds() * 1000)
    return {"data": resp, "meta": {"tool_call_id": tc["id"], "http_status": 201, "latency_ms": latency_ms}}

def create_issue(connection_id, repo_full_name, title, body=None, labels=None, assignees=None, milestone_number=None, **_extra):
    import json, os, datetime, re, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0069000" if __import__("os").path.isdir("./environment_mix/0069000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex[:24].upper()}"

    def _choose_connection(req_connection_id):
        conns = _load("github_connections.json")
        if not (isinstance(req_connection_id, str) and re.fullmatch(r"^ghc_[0-9A-Z]{18,}$", req_connection_id or "") is not None):
            return None
        for c in conns:
            if isinstance(c, dict) and c.get("id") == req_connection_id and c.get("status") == "active":
                return c
        return None

    def _log_call(tool_name, conn_id, request_obj, resolved_repo_full_name=None, repo_id=None, issue_pr_id=None):
        calls = _load("github_tool_calls.json")
        cid = _new_id("gtc")
        now = _now()
        row = {
            "id": cid,
            "connection_id": conn_id,
            "tool_name": tool_name,
            "request_json": request_obj if isinstance(request_obj, dict) else {},
            "resolved_repo_full_name": resolved_repo_full_name,
            "repo_id": repo_id,
            "issue_pr_id": issue_pr_id,
            "http_status": None,
            "rate_limit_remaining": None,
            "rate_limit_reset_at": None,
            "status": "queued",
            "error_code": None,
            "error_message": None,
            "response_json": None,
            "started_at": None,
            "finished_at": None,
            "created_at": now,
            "updated_at": now,
        }
        calls.append(row)
        _save("github_tool_calls.json", calls)
        now2 = _now()
        for r in calls:
            if isinstance(r, dict) and r.get("id") == cid:
                r["status"] = "running"
                r["started_at"] = r.get("started_at") or now2
                r["updated_at"] = now2
                break
        _save("github_tool_calls.json", calls)
        return cid

    def _finish_call(call_id, status, http_status=None, response_json=None, error_code=None, error_message=None, repo_id=None, issue_pr_id=None):
        calls = _load("github_tool_calls.json")
        finished = _now()
        allowed = {"queued": {"running", "failed"}, "running": {"succeeded", "failed"}, "succeeded": set(), "failed": set()}
        for r in calls:
            if isinstance(r, dict) and r.get("id") == call_id:
                cur = r.get("status")
                if cur in allowed and status in allowed[cur]:
                    r["status"] = status
                else:
                    r["status"] = status
                r["http_status"] = http_status
                r["response_json"] = response_json
                r["error_code"] = error_code
                r["error_message"] = error_message
                if repo_id is not None:
                    r["repo_id"] = repo_id
                if issue_pr_id is not None:
                    r["issue_pr_id"] = issue_pr_id
                r["finished_at"] = finished
                r["updated_at"] = finished
                break
        _save("github_tool_calls.json", calls)

    # Validate
    if not (isinstance(connection_id, str) and re.fullmatch(r"^ghc_[0-9A-Z]{18,}$", connection_id) is not None):
        return _err("VALIDATION_ERROR", "Invalid connection_id.")
    if not (isinstance(repo_full_name, str) and "/" in repo_full_name and len(repo_full_name.split("/", 1)[0]) > 0 and len(repo_full_name.split("/", 1)[1]) > 0):
        return _err("VALIDATION_ERROR", "repo_full_name must be in 'owner/name' form.", repo_full_name=repo_full_name)
    if not isinstance(title, str) or title.strip() == "":
        return _err("VALIDATION_ERROR", "title must be a non-empty string.")
    if body is not None and not isinstance(body, str):
        return _err("VALIDATION_ERROR", "body must be a string when provided.")
    if labels is not None and (not isinstance(labels, list) or any(not isinstance(x, str) for x in labels)):
        return _err("VALIDATION_ERROR", "labels must be an array of strings when provided.")
    if assignees is not None and (not isinstance(assignees, list) or any(not isinstance(x, str) for x in assignees)):
        return _err("VALIDATION_ERROR", "assignees must be an array of strings when provided.")
    if milestone_number is not None and not isinstance(milestone_number, int):
        return _err("VALIDATION_ERROR", "milestone_number must be an integer when provided.")

    conn = _choose_connection(connection_id)
    if not conn:
        return _err("UNAUTHORIZED", "Invalid or inactive connection_id.", connection_id=connection_id)

    repos = _load("github_repositories.json")
    repo = None
    for r in repos:
        if isinstance(r, dict) and r.get("full_name") == repo_full_name and r.get("status") != "deleted":
            repo = r
            break

    call_id = _log_call(
        "create_issue",
        conn.get("id"),
        {
            "connection_id": connection_id,
            "repo_full_name": repo_full_name,
            "title": title,
            "body": body,
            "labels": labels,
            "assignees": assignees,
            "milestone_number": milestone_number,
        },
        resolved_repo_full_name=repo_full_name,
        repo_id=repo.get("id") if repo else None,
    )

    if repo is None:
        _finish_call(call_id, "failed", http_status=404, error_code="github_404", error_message="Repository not found.")
        return _err("NOT_FOUND", "Repository not found.", repo_full_name=repo_full_name)

    issues = _load("github_issues_pull_requests.json")

    # assign next number unique per repo
    max_num = 0
    max_gid = 0
    for it in issues:
        if not isinstance(it, dict):
            continue
        if it.get("repo_id") == repo.get("id"):
            n = it.get("number")
            if isinstance(n, int) and n > max_num:
                max_num = n
            gid = it.get("github_issue_id")
            if isinstance(gid, int) and gid > max_gid:
                max_gid = gid

    new_number = max_num + 1
    new_github_issue_id = max_gid + 1 if max_gid > 0 else 1

    # Enforce uniqueness
    for it in issues:
        if isinstance(it, dict) and it.get("repo_id") == repo.get("id") and it.get("number") == new_number:
            _finish_call(call_id, "failed", http_status=409, error_code="github_409", error_message="Issue number conflict.")
            return _err("CONFLICT", "Issue number conflict.", repo_id=repo.get("id"), number=new_number)

    now = _now()
    issue_id = _new_id("ghi")
    row = {
        "id": issue_id,
        "repo_id": repo.get("id"),
        "github_issue_id": new_github_issue_id,
        "number": new_number,
        "kind": "issue",
        "title": title,
        "body": body,
        "author_login": conn.get("github_login"),
        "labels": labels if isinstance(labels, list) else [],
        "assignees": assignees if isinstance(assignees, list) else [],
        "milestone_number": milestone_number,
        "state": "open",
        "locked": False,
        "closed_at": None,
        "is_draft": None,
        "base_branch": None,
        "head_branch": None,
        "head_repo_full_name": None,
        "mergeable_state": None,
        "merged": None,
        "merged_at": None,
        "merged_by_login": None,
        "status": "active",
        "github_updated_at": now,
        "created_at": now,
        "updated_at": now,
    }
    issues.append(row)
    _save("github_issues_pull_requests.json", issues)

    resp = {
        "id": row["id"],
        "repo_full_name": repo_full_name,
        "number": row["number"],
        "state": row["state"],
        "title": row["title"],
        "body": row["body"],
        "labels": row["labels"],
        "assignees": row["assignees"],
        "milestone_number": row["milestone_number"],
        "created_at": row["created_at"],
        "updated_at": row["updated_at"],
    }
    _finish_call(call_id, "succeeded", http_status=201, response_json=resp, repo_id=repo.get("id"), issue_pr_id=issue_id)
    return resp

def list_commits(repo_full_name, branch, path=None, author=None, since=None, until=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, re, time, uuid, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0069000" if __import__("os").path.isdir("./environment_mix/0069000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _gen_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _parse_full_name(v):
        if not isinstance(v, str):
            return None
        v = v.strip()
        if v.count("/") != 1:
            return None
        owner, name = v.split("/", 1)
        if not owner or not name:
            return None
        return owner, name, f"{owner}/{name}"

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return "bad"
        try:
            ss = s.strip()
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(ss).astimezone(datetime.timezone.utc)
        except Exception:
            return "bad"

    def _is_valid_branch_name(b):
        if not isinstance(b, str):
            return False
        b = b.strip()
        if not b:
            return False
        if b.startswith("/") or b.endswith("/") or "//" in b:
            return False
        if ".." in b or "@{" in b or b.endswith(".lock"):
            return False
        if any(c.isspace() for c in b):
            return False
        bad = set('~^:?*[\\')
        if any(c in bad for c in b):
            return False
        parts = b.split("/")
        if any(p in (".", "..") or p == "" for p in parts):
            return False
        if any(ord(c) < 32 or ord(c) == 127 for c in b):
            return False
        return True

    def _encode_cursor(offset):
        raw = json.dumps({"offset": offset}, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")

    def _decode_cursor(cur):
        if cur is None:
            return 0
        if not isinstance(cur, str) or not cur:
            return None
        pad = "=" * (-len(cur) % 4)
        try:
            raw = base64.urlsafe_b64decode((cur + pad).encode("ascii"))
            obj = json.loads(raw.decode("utf-8"))
            off = obj.get("offset")
            if isinstance(off, int) and off >= 0:
                return off
            return None
        except Exception:
            return None

    tool_calls = _load("github_tool_calls.json")
    connections = _load("github_connections.json")
    repos = _load("github_repositories.json")
    objs = _load("github_git_objects.json")

    start = time.time()
    req = {
        "repo_full_name": repo_full_name,
        "branch": branch,
        "path": path,
        "author": author,
        "since": since,
        "until": until,
        "limit": limit,
        "cursor": cursor,
    }

    parsed = _parse_full_name(repo_full_name)
    if not parsed:
        tc_id = _gen_id("gtc")
        now = _now()
        tool_calls.append({
            "id": tc_id,
            "connection_id": "unknown",
            "tool_name": "list_commits",
            "request_json": req,
            "resolved_repo_full_name": None,
            "repo_id": None,
            "issue_pr_id": None,
            "http_status": 400,
            "rate_limit_remaining": None,
            "rate_limit_reset_at": None,
            "status": "failed",
            "error_code": "validation_error",
            "error_message": "repo_full_name must be in 'owner/name' form.",
            "response_json": None,
            "started_at": now,
            "finished_at": now,
            "created_at": now,
            "updated_at": now,
        })
        _save("github_tool_calls.json", tool_calls)
        return _err("VALIDATION_ERROR", "repo_full_name must be in 'owner/name' form.", field="repo_full_name")
    _, _, full_name = parsed

    if not _is_valid_branch_name(branch):
        tc_id = _gen_id("gtc")
        now = _now()
        tool_calls.append({
            "id": tc_id,
            "connection_id": "unknown",
            "tool_name": "list_commits",
            "request_json": req,
            "resolved_repo_full_name": full_name,
            "repo_id": None,
            "issue_pr_id": None,
            "http_status": 400,
            "rate_limit_remaining": None,
            "rate_limit_reset_at": None,
            "status": "failed",
            "error_code": "validation_error",
            "error_message": "Invalid branch name.",
            "response_json": None,
            "started_at": now,
            "finished_at": now,
            "created_at": now,
            "updated_at": now,
        })
        _save("github_tool_calls.json", tool_calls)
        return _err("VALIDATION_ERROR", "Invalid branch name.", field="branch")

    if limit is None:
        limit_v = 30
    else:
        if not isinstance(limit, int):
            return _err("VALIDATION_ERROR", "limit must be an integer.", field="limit")
        if limit < 1 or limit > 100:
            return _err("VALIDATION_ERROR", "limit must be between 1 and 100.", field="limit")
        limit_v = limit

    since_dt = _parse_dt(since)
    if since_dt == "bad":
        return _err("VALIDATION_ERROR", "since must be an ISO date-time string.", field="since")
    until_dt = _parse_dt(until)
    if until_dt == "bad":
        return _err("VALIDATION_ERROR", "until must be an ISO date-time string.", field="until")

    offset = _decode_cursor(cursor)
    if offset is None:
        return _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")

    repo = None
    for r in repos:
        if r.get("full_name") == full_name:
            repo = r
            break
    if not repo:
        # still must log call as failed
        tc_id = _gen_id("gtc")
        now = _now()
        tool_calls.append({
            "id": tc_id,
            "connection_id": "unknown",
            "tool_name": "list_commits",
            "request_json": req,
            "resolved_repo_full_name": full_name,
            "repo_id": None,
            "issue_pr_id": None,
            "http_status": 404,
            "rate_limit_remaining": None,
            "rate_limit_reset_at": None,
            "status": "failed",
            "error_code": "github_404",
            "error_message": "Repository not found.",
            "response_json": None,
            "started_at": now,
            "finished_at": now,
            "created_at": now,
            "updated_at": now,
        })
        _save("github_tool_calls.json", tool_calls)
        return _err("NOT_FOUND", "Repository not found.", repo_full_name=full_name)

    # Resolve an authorized connection (ambient)
    conn = None
    if repo.get("connection_id"):
        for c in connections:
            if c.get("id") == repo.get("connection_id") and c.get("status") == "active":
                conn = c
                break
    if not conn:
        for c in connections:
            if c.get("status") == "active":
                conn = c
                break
    if not conn:
        tc_id = _gen_id("gtc")
        now = _now()
        tool_calls.append({
            "id": tc_id,
            "connection_id": "unknown",
            "tool_name": "list_commits",
            "request_json": req,
            "resolved_repo_full_name": full_name,
            "repo_id": repo.get("id"),
            "issue_pr_id": None,
            "http_status": 401,
            "rate_limit_remaining": None,
            "rate_limit_reset_at": None,
            "status": "failed",
            "error_code": "github_401",
            "error_message": "No active GitHub connection available.",
            "response_json": None,
            "started_at": now,
            "finished_at": now,
            "created_at": now,
            "updated_at": now,
        })
        _save("github_tool_calls.json", tool_calls)
        return _err("UNAUTHORIZED", "No active GitHub connection available.")

    # Insert tool call row (queued) then running
    tc_id = _gen_id("gtc")
    now = _now()
    tool_calls.append({
        "id": tc_id,
        "connection_id": conn["id"],
        "tool_name": "list_commits",
        "request_json": req,
        "resolved_repo_full_name": full_name,
        "repo_id": repo.get("id"),
        "issue_pr_id": None,
        "http_status": None,
        "rate_limit_remaining": None,
        "rate_limit_reset_at": None,
        "status": "queued",
        "error_code": None,
        "error_message": None,
        "response_json": None,
        "started_at": None,
        "finished_at": None,
        "created_at": now,
        "updated_at": now,
    })
    _save("github_tool_calls.json", tool_calls)

    started = _now()
    for t in tool_calls:
        if t.get("id") == tc_id:
            t["status"] = "running"
            t["started_at"] = started
            t["updated_at"] = started
            break
    _save("github_tool_calls.json", tool_calls)

    # Cache read
    commits = [o for o in objs if o.get("repo_id") == repo["id"] and o.get("object_type") == "commit" and o.get("status") != "tombstoned"]

    def _commit_dt(o):
        dt = _parse_dt(o.get("committed_at"))
        if isinstance(dt, datetime.datetime):
            return dt
        return datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)

    # If cache miss, simulate "fetch from GitHub" by failing gracefully with empty list but succeeded call
    # (real GitHub would return list; offline store cannot). We'll still succeed with cached results (possibly empty).
    # Apply filters
    if author is not None:
        if not isinstance(author, str):
            finished = _now()
            for t in tool_calls:
                if t.get("id") == tc_id:
                    t["status"] = "failed"
                    t["http_status"] = 400
                    t["error_code"] = "validation_error"
                    t["error_message"] = "author must be a string."
                    t["finished_at"] = finished
                    t["updated_at"] = finished
                    break
            _save("github_tool_calls.json", tool_calls)
            return _err("VALIDATION_ERROR", "author must be a string.", field="author")
        a = author.strip().lower()
        commits = [c for c in commits if (isinstance(c.get("author_login"), str) and c["author_login"].lower() == a) or (isinstance(c.get("author_email"), str) and c["author_email"].lower() == a)]

    if since_dt is not None:
        commits = [c for c in commits if _commit_dt(c) >= since_dt]
    if until_dt is not None:
        commits = [c for c in commits if _commit_dt(c) <= until_dt]

    # branch/path are not modeled on commit objects in schema beyond path (used for blobs/trees),
    # so we can only filter by branch if we can traverse from branch ref head (not stored graph).
    # We'll keep branch as informational; if a ref exists, we can prioritize commits matching its head sha.
    head_sha = None
    ref_name = f"refs/heads/{branch}"
    for o in objs:
        if o.get("repo_id") == repo["id"] and o.get("object_type") == "ref" and o.get("ref_name") == ref_name and o.get("status") != "tombstoned":
            head_sha = o.get("sha")
            break

    # Sort newest-first by committed_at; if head_sha present, bring that commit to front
    commits.sort(key=_commit_dt, reverse=True)
    if head_sha:
        for i, c in enumerate(commits):
            if c.get("sha") == head_sha:
                commits.insert(0, commits.pop(i))
                break

    # path filter cannot be precisely applied; accept only if provided as string
    if path is not None and not isinstance(path, str):
        finished = _now()
        for t in tool_calls:
            if t.get("id") == tc_id:
                t["status"] = "failed"
                t["http_status"] = 400
                t["error_code"] = "validation_error"
                t["error_message"] = "path must be a string."
                t["finished_at"] = finished
                t["updated_at"] = finished
                break
        _save("github_tool_calls.json", tool_calls)
        return _err("VALIDATION_ERROR", "path must be a string.", field="path")

    total = len(commits)
    page = commits[offset:offset + limit_v]
    next_off = offset + len(page)
    has_more = next_off < total
    next_cursor = _encode_cursor(next_off) if has_more else None

    items = []
    for c in page:
        items.append({
            "sha": c.get("sha"),
            "message": c.get("message"),
            "author_login": c.get("author_login"),
            "author_email": c.get("author_email"),
            "committed_at": c.get("committed_at"),
            "parents": c.get("parent_sha_list") or [],
        })

    finished = _now()
    resp = {
        "commits": items,
        "cursor": next_cursor,
    }
    for t in tool_calls:
        if t.get("id") == tc_id:
            t["status"] = "succeeded"
            t["http_status"] = 200
            t["response_json"] = {"total": total, "returned": len(items), "cursor": next_cursor}
            t["finished_at"] = finished
            t["updated_at"] = finished
            break
    _save("github_tool_calls.json", tool_calls)

    return {
        "data": resp,
        "meta": {
            "repo_full_name": full_name,
            "branch": branch,
            "total": total,
            "returned": len(items),
            "has_more": has_more,
            "next_cursor": next_cursor,
            "tool_call_id": tc_id,
            "latency_ms": int((time.time() - start) * 1000),
        },
    }

def list_issues(repo_full_name, state=None, labels=None, assignee=None, creator=None, mentioned=None, milestone=None, sort=None, direction=None, since=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, uuid, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0069000" if __import__("os").path.isdir("./environment_mix/0069000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _gen_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _parse_full_name(v):
        if not isinstance(v, str):
            return None
        v = v.strip()
        if v.count("/") != 1:
            return None
        owner, name = v.split("/", 1)
        if not owner or not name:
            return None
        return owner, name, f"{owner}/{name}"

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return "bad"
        try:
            ss = s.strip()
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(ss).astimezone(datetime.timezone.utc)
        except Exception:
            return "bad"

    def _encode_cursor(offset):
        raw = json.dumps({"offset": offset}, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")

    def _decode_cursor(cur):
        if cur is None:
            return 0
        if not isinstance(cur, str) or not cur:
            return None
        pad = "=" * (-len(cur) % 4)
        try:
            raw = base64.urlsafe_b64decode((cur + pad).encode("ascii"))
            obj = json.loads(raw.decode("utf-8"))
            off = obj.get("offset")
            if isinstance(off, int) and off >= 0:
                return off
            return None
        except Exception:
            return None

    tool_calls = _load("github_tool_calls.json")
    connections = _load("github_connections.json")
    repos = _load("github_repositories.json")
    issues = _load("github_issues_pull_requests.json")

    start = time.time()
    req = {
        "repo_full_name": repo_full_name,
        "state": state,
        "labels": labels,
        "assignee": assignee,
        "creator": creator,
        "mentioned": mentioned,
        "milestone": milestone,
        "sort": sort,
        "direction": direction,
        "since": since,
        "limit": limit,
        "cursor": cursor,
    }

    parsed = _parse_full_name(repo_full_name)
    if not parsed:
        tc_id = _gen_id("gtc")
        now = _now()
        tool_calls.append({
            "id": tc_id,
            "connection_id": "unknown",
            "tool_name": "list_issues",
            "request_json": req,
            "resolved_repo_full_name": None,
            "repo_id": None,
            "issue_pr_id": None,
            "http_status": 400,
            "rate_limit_remaining": None,
            "rate_limit_reset_at": None,
            "status": "failed",
            "error_code": "validation_error",
            "error_message": "repo_full_name must be in 'owner/name' form.",
            "response_json": None,
            "started_at": now,
            "finished_at": now,
            "created_at": now,
            "updated_at": now,
        })
        _save("github_tool_calls.json", tool_calls)
        return _err("VALIDATION_ERROR", "repo_full_name must be in 'owner/name' form.", field="repo_full_name")
    _, _, full_name = parsed

    state_v = state or "open"
    if state_v not in ("open", "closed", "all"):
        return _err("VALIDATION_ERROR", "Invalid state. Must be one of open, closed, all.", field="state")
    sort_v = sort or "created"
    if sort_v not in ("created", "updated", "comments"):
        return _err("VALIDATION_ERROR", "Invalid sort. Must be one of created, updated, comments.", field="sort")
    direction_v = direction or "desc"
    if direction_v not in ("asc", "desc"):
        return _err("VALIDATION_ERROR", "Invalid direction. Must be asc or desc.", field="direction")

    if limit is None:
        limit_v = 30
    else:
        if not isinstance(limit, int):
            return _err("VALIDATION_ERROR", "limit must be an integer.", field="limit")
        if limit < 1 or limit > 100:
            return _err("VALIDATION_ERROR", "limit must be between 1 and 100.", field="limit")
        limit_v = limit

    if labels is not None:
        if not isinstance(labels, list) or any(not isinstance(x, str) for x in labels):
            return _err("VALIDATION_ERROR", "labels must be an array of strings.", field="labels")
        labels_v = [x.strip() for x in labels if x.strip() != ""]
    else:
        labels_v = None

    for fld, val in (("assignee", assignee), ("creator", creator), ("mentioned", mentioned), ("milestone", milestone)):
        if val is not None and not isinstance(val, str):
            return _err("VALIDATION_ERROR", f"{fld} must be a string.", field=fld)

    since_dt = _parse_dt(since)
    if since_dt == "bad":
        return _err("VALIDATION_ERROR", "since must be an ISO date-time string.", field="since")

    offset = _decode_cursor(cursor)
    if offset is None:
        return _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")

    repo = None
    for r in repos:
        if r.get("full_name") == full_name:
            repo = r
            break
    if not repo:
        tc_id = _gen_id("gtc")
        now = _now()
        tool_calls.append({
            "id": tc_id,
            "connection_id": "unknown",
            "tool_name": "list_issues",
            "request_json": req,
            "resolved_repo_full_name": full_name,
            "repo_id": None,
            "issue_pr_id": None,
            "http_status": 404,
            "rate_limit_remaining": None,
            "rate_limit_reset_at": None,
            "status": "failed",
            "error_code": "github_404",
            "error_message": "Repository not found.",
            "response_json": None,
            "started_at": now,
            "finished_at": now,
            "created_at": now,
            "updated_at": now,
        })
        _save("github_tool_calls.json", tool_calls)
        return _err("NOT_FOUND", "Repository not found.", repo_full_name=full_name)

    # Resolve authorized connection
    conn = None
    if repo.get("connection_id"):
        for c in connections:
            if c.get("id") == repo.get("connection_id") and c.get("status") == "active":
                conn = c
                break
    if not conn:
        for c in connections:
            if c.get("status") == "active":
                conn = c
                break
    if not conn:
        tc_id = _gen_id("gtc")
        now = _now()
        tool_calls.append({
            "id": tc_id,
            "connection_id": "unknown",
            "tool_name": "list_issues",
            "request_json": req,
            "resolved_repo_full_name": full_name,
            "repo_id": repo.get("id"),
            "issue_pr_id": None,
            "http_status": 401,
            "rate_limit_remaining": None,
            "rate_limit_reset_at": None,
            "status": "failed",
            "error_code": "github_401",
            "error_message": "No active GitHub connection available.",
            "response_json": None,
            "started_at": now,
            "finished_at": now,
            "created_at": now,
            "updated_at": now,
        })
        _save("github_tool_calls.json", tool_calls)
        return _err("UNAUTHORIZED", "No active GitHub connection available.")

    # Insert tool call row (queued) then running
    tc_id = _gen_id("gtc")
    now = _now()
    tool_calls.append({
        "id": tc_id,
        "connection_id": conn["id"],
        "tool_name": "list_issues",
        "request_json": req,
        "resolved_repo_full_name": full_name,
        "repo_id": repo.get("id"),
        "issue_pr_id": None,
        "http_status": None,
        "rate_limit_remaining": None,
        "rate_limit_reset_at": None,
        "status": "queued",
        "error_code": None,
        "error_message": None,
        "response_json": None,
        "started_at": None,
        "finished_at": None,
        "created_at": now,
        "updated_at": now,
    })
    _save("github_tool_calls.json", tool_calls)

    started = _now()
    for t in tool_calls:
        if t.get("id") == tc_id:
            t["status"] = "running"
            t["started_at"] = started
            t["updated_at"] = started
            break
    _save("github_tool_calls.json", tool_calls)

    # Filter to issues only, active only
    rows = [i for i in issues if i.get("repo_id") == repo["id"] and i.get("kind") == "issue" and i.get("status") != "deleted"]

    if state_v != "all":
        rows = [i for i in rows if i.get("state") == state_v]

    if labels_v is not None:
        def _labels_match(issue_row):
            issue_labels = issue_row.get("labels") or []
            if not isinstance(issue_labels, list):
                return False
            s = set([x for x in issue_labels if isinstance(x, str)])
            return all(l in s for l in labels_v)
        rows = [i for i in rows if _labels_match(i)]

    if assignee is not None:
        a = assignee.strip()
        if a.lower() == "none":
            rows = [i for i in rows if not (i.get("assignees") or [])]
        else:
            rows = [i for i in rows if isinstance(i.get("assignees"), list) and any(isinstance(x, str) and x == a for x in i.get("assignees"))]

    if creator is not None:
        c = creator.strip()
        rows = [i for i in rows if i.get("author_login") == c]

    if mentioned is not None:
        m = mentioned.strip()
        # naive: check in body or title
        def _mentions(i):
            t = i.get("title") or ""
            b = i.get("body") or ""
            if not isinstance(t, str): t = ""
            if not isinstance(b, str): b = ""
            return m in t or m in b
        rows = [i for i in rows if _mentions(i)]

    if milestone is not None:
        ms = milestone.strip()
        if ms == "none":
            rows = [i for i in rows if i.get("milestone_number") is None]
        elif ms == "*":
            rows = [i for i in rows if i.get("milestone_number") is not None]
        else:
            try:
                msn = int(ms)
                rows = [i for i in rows if i.get("milestone_number") == msn]
            except Exception:
                finished = _now()
                for t in tool_calls:
                    if t.get("id") == tc_id:
                        t["status"] = "failed"
                        t["http_status"] = 400
                        t["error_code"] = "validation_error"
                        t["error_message"] = "milestone must be a number as string, 'none', or '*'."
                        t["finished_at"] = finished
                        t["updated_at"] = finished
                        break
                _save("github_tool_calls.json", tool_calls)
                return _err("VALIDATION_ERROR", "milestone must be a number as string, 'none', or '*'.", field="milestone")

    if since_dt is not None:
        def _upd_dt(i):
            sdt = i.get("github_updated_at") or i.get("updated_at")
            dt = _parse_dt(sdt)
            if isinstance(dt, datetime.datetime):
                return dt
            return datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        rows = [i for i in rows if _upd_dt(i) >= since_dt]

    # Sort
    def _sort_key(i):
        if sort_v == "created":
            return i.get("created_at") or ""
        if sort_v == "updated":
            return i.get("github_updated_at") or i.get("updated_at") or ""
        # comments: not available; fallback to updated
        return i.get("github_updated_at") or i.get("updated_at") or ""

    rows.sort(key=_sort_key, reverse=(direction_v == "desc"))

    total = len(rows)
    page = rows[offset:offset + limit_v]
    next_off = offset + len(page)
    has_more = next_off < total
    next_cursor = _encode_cursor(next_off) if has_more else None

    items = []
    for i in page:
        items.append({
            "id": i.get("id"),
            "number": i.get("number"),
            "title": i.get("title"),
            "body": i.get("body"),
            "state": i.get("state"),
            "labels": i.get("labels") or [],
            "assignees": i.get("assignees") or [],
            "milestone_number": i.get("milestone_number"),
            "author_login": i.get("author_login"),
            "locked": i.get("locked"),
            "closed_at": i.get("closed_at"),
            "github_updated_at": i.get("github_updated_at"),
            "created_at": i.get("created_at"),
            "updated_at": i.get("updated_at"),
            "repo_full_name": full_name,
        })

    finished = _now()
    for t in tool_calls:
        if t.get("id") == tc_id:
            t["status"] = "succeeded"
            t["http_status"] = 200
            t["response_json"] = {"total": total, "returned": len(items), "cursor": next_cursor}
            t["finished_at"] = finished
            t["updated_at"] = finished
            break
    _save("github_tool_calls.json", tool_calls)

    return {
        "data": {"issues": items, "cursor": next_cursor},
        "meta": {
            "repo_full_name": full_name,
            "total": total,
            "returned": len(items),
            "has_more": has_more,
            "next_cursor": next_cursor,
            "tool_call_id": tc_id,
            "latency_ms": int((time.time() - start) * 1000),
        },
    }

def search_code(query, sort=None, order=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, uuid, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0069000" if __import__("os").path.isdir("./environment_mix/0069000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # Validation
    if not isinstance(query, str) or query.strip() == "":
        return _err("VALIDATION_ERROR", "query must be a non-empty string.")
    if sort is not None and sort not in ("indexed",):
        return _err("VALIDATION_ERROR", "Invalid sort value.", allowed=["indexed"])
    if order is not None and order not in ("asc", "desc"):
        return _err("VALIDATION_ERROR", "Invalid order value.", allowed=["asc", "desc"])
    if order is not None and sort is None:
        return _err("VALIDATION_ERROR", "order cannot be provided without sort.")
    if limit is None:
        limit = 30
    if not isinstance(limit, int) or limit < 1 or limit > 100:
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 100.")
    if cursor is not None and (not isinstance(cursor, str) or cursor.strip() == ""):
        return _err("VALIDATION_ERROR", "cursor must be a non-empty string when provided.")

    # Auth context (ambient)
    conns = _load("github_connections.json")
    active_conns = [c for c in conns if isinstance(c, dict) and c.get("status") == "active"]
    if not active_conns:
        return _err("UNAUTHORIZED", "No active GitHub connection available to perform this operation.")
    conn = active_conns[0]

    repos = _load("github_repositories.json")
    objs = _load("github_git_objects.json")
    calls = _load("github_tool_calls.json")

    # Log tool call: queued->running
    call_id = "gtc_" + uuid.uuid4().hex
    req_json = {"query": query, "sort": sort, "order": order, "limit": limit, "cursor": cursor}
    call_row = {
        "id": call_id,
        "connection_id": conn.get("id"),
        "tool_name": "search_code",
        "request_json": req_json,
        "resolved_repo_full_name": None,
        "repo_id": None,
        "issue_pr_id": None,
        "http_status": None,
        "rate_limit_remaining": None,
        "rate_limit_reset_at": None,
        "status": "queued",
        "error_code": None,
        "error_message": None,
        "response_json": None,
        "started_at": None,
        "finished_at": None,
        "created_at": now,
        "updated_at": now
    }
    calls.append(call_row)
    _save("github_tool_calls.json", calls)

    call_row["status"] = "running"
    call_row["started_at"] = now
    call_row["updated_at"] = now
    _save("github_tool_calls.json", calls)

    # Search quota/rate limit (simple local enforcement): max 30 searches/min per connection across search_* tools.
    window_s = 60
    max_per_window = 30
    now_dt = datetime.datetime.utcnow()
    recent = 0
    for r in calls:
        if not isinstance(r, dict):
            continue
        if r.get("connection_id") != conn.get("id"):
            continue
        if r.get("tool_name") not in ("search_code", "search_issues", "search_users", "search_repositories"):
            continue
        ts = r.get("created_at")
        if isinstance(ts, str) and ts.endswith("Z"):
            try:
                dt = datetime.datetime.fromisoformat(ts[:-1])
            except Exception:
                continue
            if (now_dt - dt).total_seconds() <= window_s:
                recent += 1
    if recent > max_per_window:
        call_row["status"] = "failed"
        call_row["http_status"] = 429
        call_row["error_code"] = "rate_limited"
        call_row["error_message"] = "Search rate limit exceeded."
        call_row["finished_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        call_row["updated_at"] = call_row["finished_at"]
        _save("github_tool_calls.json", calls)
        return _err("RATE_LIMIT", "Search rate limit exceeded. Please retry later.")

    # Cursor handling: cursor is base64-encoded integer offset
    offset = 0
    if cursor is not None:
        try:
            offset = int(base64.urlsafe_b64decode(cursor.encode("utf-8")).decode("utf-8"))
            if offset < 0:
                raise ValueError()
        except Exception:
            call_row["status"] = "failed"
            call_row["http_status"] = 400
            call_row["error_code"] = "validation_error"
            call_row["error_message"] = "Invalid cursor."
            call_row["finished_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
            call_row["updated_at"] = call_row["finished_at"]
            _save("github_tool_calls.json", calls)
            return _err("VALIDATION_ERROR", "Invalid cursor.")

    q = query.strip().lower()

    # Local indexed snapshots: search cached blobs' content_text and path
    # Only blobs with status present/stale (not tombstoned) and repo status not deleted/access_revoked
    repo_by_id = {r.get("id"): r for r in repos if isinstance(r, dict)}
    hits = []
    for o in objs:
        if not isinstance(o, dict):
            continue
        if o.get("object_type") != "blob":
            continue
        if o.get("status") == "tombstoned":
            continue
        rid = o.get("repo_id")
        r = repo_by_id.get(rid)
        if not r or r.get("status") in ("deleted", "access_revoked"):
            continue
        path = o.get("path") or ""
        content = o.get("content_text") or ""
        if q in path.lower() or q in content.lower():
            hits.append({
                "repo_full_name": r.get("full_name"),
                "repo_id": rid,
                "path": path,
                "sha": o.get("sha"),
                "snippet": (content[:200] if isinstance(content, str) else None),
                "last_indexed_at": o.get("last_fetched_at") or o.get("updated_at")
            })

    # Sorting (only 'indexed' supported): use last_indexed_at desc/asc
    if sort == "indexed":
        def keyfun(x):
            v = x.get("last_indexed_at")
            return v or ""
        hits.sort(key=keyfun, reverse=(order != "asc"))

    total = len(hits)
    page = hits[offset: offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = None
    if has_more:
        next_cursor = base64.urlsafe_b64encode(str(next_offset).encode("utf-8")).decode("utf-8")

    # Finish tool call success
    call_row["status"] = "succeeded"
    call_row["http_status"] = 200
    call_row["response_json"] = {"total": total, "returned": len(page), "next_cursor": next_cursor}
    call_row["finished_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    call_row["updated_at"] = call_row["finished_at"]
    _save("github_tool_calls.json", calls)

    return {
        "items": page,
        "cursor": next_cursor,
        "total": total,
        "has_more": has_more,
        "meta": {"latency_ms": int((time.time() - t0) * 1000)}
    }

