        call_row["error_code"] = "rate_limited"
        call_row["error_message"] = "Search rate limit exceeded."
        call_row["finished_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        call_row["updated_at"] = call_row["finished_at"]
        _save("github_tool_calls.json", calls)
        return _err("RATE_LIMIT", "Search rate limit exceeded. Please retry later.")

    # Cursor decode
    offset = 0
    if cursor is not None:
        try:
            offset = int(base64.urlsafe_b64decode(cursor.encode("utf-8")).decode("utf-8"))
            if offset < 0:
                raise ValueError()
        except Exception:
            call_row["status"] = "failed"
            call_row["http_status"] = 400
            call_row["error_code"] = "validation_error"
            call_row["error_message"] = "Invalid cursor."
            call_row["finished_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
            call_row["updated_at"] = call_row["finished_at"]
            _save("github_tool_calls.json", calls)
            return _err("VALIDATION_ERROR", "Invalid cursor.")

    q = query.strip().lower()

    repo_by_id = {r.get("id"): r for r in repos if isinstance(r, dict)}
    # simple query parsing: optional "repo:owner/name" token
    repo_filter = None
    m = re.search(r'(^|\s)repo:([A-Za-z0-9_.-]+/[A-Za-z0-9_.-]+)($|\s)', query)
    if m:
        repo_filter = m.group(2)

    def visible(it):
        if it.get("status") not in ("active",):
            return False
        r = repo_by_id.get(it.get("repo_id"))
        if not r:
            return False
        if r.get("status") in ("deleted", "access_revoked"):
            return False
        return True

    results = []
    for it in issues:
        if not isinstance(it, dict):
            continue
        if not visible(it):
            continue
        r = repo_by_id.get(it.get("repo_id"))
        if repo_filter and (not r or r.get("full_name") != repo_filter):
            continue
        hay = " ".join([
            str(r.get("full_name") if r else ""),
            str(it.get("number") or ""),
            str(it.get("title") or ""),
            str(it.get("body") or ""),
            str(it.get("author_login") or ""),
            " ".join([str(x) for x in (it.get("labels") or [])]),
            " ".join([str(x) for x in (it.get("assignees") or [])]),
            str(it.get("kind") or ""),
            str(it.get("state") or ""),
        ]).lower()
        if q in hay:
            results.append({
                "id": it.get("id"),
                "repo_full_name": (r.get("full_name") if r else None),
                "repo_id": it.get("repo_id"),
                "number": it.get("number"),
                "kind": it.get("kind"),
                "title": it.get("title"),
                "state": it.get("state"),
                "author_login": it.get("author_login"),
                "github_updated_at": it.get("github_updated_at"),
                "created_at": it.get("created_at"),
                "updated_at": it.get("updated_at"),
            })

    # sort
    reverse = (order != "asc")
    if sort == "created":
        results.sort(key=lambda x: x.get("created_at") or "", reverse=reverse)
    elif sort == "updated":
        results.sort(key=lambda x: x.get("github_updated_at") or x.get("updated_at") or "", reverse=reverse)
    elif sort == "comments":
        # proxy sort: by number of cached discussion artifacts
        arts = _load("github_discussion_artifacts.json")
        count_by_issue = {}
        for a in arts:
            if isinstance(a, dict) and a.get("issue_pr_id"):
                count_by_issue[a.get("issue_pr_id")] = count_by_issue.get(a.get("issue_pr_id"), 0) + 1
        results.sort(key=lambda x: count_by_issue.get(x.get("id"), 0), reverse=reverse)

    total = len(results)
    page = results[offset: offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = base64.urlsafe_b64encode(str(next_offset).encode("utf-8")).decode("utf-8") if has_more else None

    call_row["status"] = "succeeded"
    call_row["http_status"] = 200
    call_row["response_json"] = {"total": total, "returned": len(page), "next_cursor": next_cursor}
    call_row["finished_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    call_row["updated_at"] = call_row["finished_at"]
    _save("github_tool_calls.json", calls)

    return {
        "items": page,
        "cursor": next_cursor,
        "total": total,
        "has_more": has_more,
        "meta": {"latency_ms": int((time.time() - t0) * 1000)}
    }

def search_users(query, sort=None, order=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, uuid, base64, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0069000" if __import__("os").path.isdir("./environment_mix/0069000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # Validation
    if not isinstance(query, str) or query.strip() == "":
        return _err("VALIDATION_ERROR", "query must be a non-empty string.")
    if sort is not None and sort not in ("followers", "repositories", "joined"):
        return _err("VALIDATION_ERROR", "Invalid sort value.", allowed=["followers", "repositories", "joined"])
    if order is not None and order not in ("asc", "desc"):
        return _err("VALIDATION_ERROR", "Invalid order value.", allowed=["asc", "desc"])
    if order is not None and sort is None:
        return _err("VALIDATION_ERROR", "order cannot be provided without sort.")
    if limit is None:
        limit = 30
    if not isinstance(limit, int) or limit < 1 or limit > 100:
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 100.")
    if cursor is not None and (not isinstance(cursor, str) or cursor.strip() == ""):
        return _err("VALIDATION_ERROR", "cursor must be a non-empty string when provided.")

    # Auth context (ambient)
    conns = _load("github_connections.json")
    active_conns = [c for c in conns if isinstance(c, dict) and c.get("status") == "active"]
    if not active_conns:
        return _err("UNAUTHORIZED", "No active GitHub connection available to perform this operation.")
    conn = active_conns[0]

    calls = _load("github_tool_calls.json")

    # Log tool call
    call_id = "gtc_" + uuid.uuid4().hex
    req_json = {"query": query, "sort": sort, "order": order, "limit": limit, "cursor": cursor}
    call_row = {
        "id": call_id,
        "connection_id": conn.get("id"),
        "tool_name": "search_users",
        "request_json": req_json,
        "resolved_repo_full_name": None,
        "repo_id": None,
        "issue_pr_id": None,
        "http_status": None,
        "rate_limit_remaining": None,
        "rate_limit_reset_at": None,
        "status": "queued",
        "error_code": None,
        "error_message": None,
        "response_json": None,
        "started_at": None,
        "finished_at": None,
        "created_at": now,
        "updated_at": now
    }
    calls.append(call_row)
    _save("github_tool_calls.json", calls)

    call_row["status"] = "running"
    call_row["started_at"] = now
    call_row["updated_at"] = now
    _save("github_tool_calls.json", calls)

    # Rate limit: max 30 searches/min per connection across search_* tools.
    window_s = 60
    max_per_window = 30
    now_dt = datetime.datetime.utcnow()
    recent = 0
    for r in calls:
        if not isinstance(r, dict):
            continue
        if r.get("connection_id") != conn.get("id"):
            continue
        if r.get("tool_name") not in ("search_code", "search_issues", "search_users", "search_repositories"):
            continue
        ts = r.get("created_at")
        if isinstance(ts, str) and ts.endswith("Z"):
            try:
                dt = datetime.datetime.fromisoformat(ts[:-1])
            except Exception:
                continue
            if (now_dt - dt).total_seconds() <= window_s:
                recent += 1
    if recent > max_per_window:
        call_row["status"] = "failed"
        call_row["http_status"] = 429
        call_row["error_code"] = "rate_limited"
        call_row["error_message"] = "Search rate limit exceeded."
        call_row["finished_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        call_row["updated_at"] = call_row["finished_at"]
        _save("github_tool_calls.json", calls)
        return _err("RATE_LIMIT", "Search rate limit exceeded. Please retry later.")

    # Cursor decode
    offset = 0
    if cursor is not None:
        try:
            offset = int(base64.urlsafe_b64decode(cursor.encode("utf-8")).decode("utf-8"))
            if offset < 0:
                raise ValueError()
        except Exception:
            call_row["status"] = "failed"
            call_row["http_status"] = 400
            call_row["error_code"] = "validation_error"
            call_row["error_message"] = "Invalid cursor."
            call_row["finished_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
            call_row["updated_at"] = call_row["finished_at"]
            _save("github_tool_calls.json", calls)
            return _err("VALIDATION_ERROR", "Invalid cursor.")

    # There is no github_users collection. We produce results derived from observed logins in existing caches:
    # - connections.github_login
    # - issues/PRs author_login/assignees/merged_by_login
    # - discussion artifacts author_login
    # - git objects author_login
    conns = _load("github_connections.json")
    issues = _load("github_issues_pull_requests.json")
    arts = _load("github_discussion_artifacts.json")
    objs = _load("github_git_objects.json")

    candidates = {}
    def add_login(login, source=None):
        if not login or not isinstance(login, str):
            return
        key = login
        if key not in candidates:
            candidates[key] = {"login": key, "sources": set(), "first_seen_at": now}
        if source:
            candidates[key]["sources"].add(source)

    for c in conns:
        if isinstance(c, dict):
            add_login(c.get("github_login"), "connection")
    for it in issues:
        if isinstance(it, dict):
            add_login(it.get("author_login"), "issue_author")
            add_login(it.get("merged_by_login"), "merged_by")
            for a in (it.get("assignees") or []):
                add_login(a, "assignee")
    for a in arts:
        if isinstance(a, dict):
            add_login(a.get("author_login"), "comment")
    for o in objs:
        if isinstance(o, dict):
            add_login(o.get("author_login"), "commit_author")

    q = query.strip().lower()
    # simple match: substring in login
    items = []
    for login, v in candidates.items():
        if q in login.lower():
            items.append({
                "login": login,
                "type": None,
                "score": 1.0,
                "observed_in": sorted(list(v["sources"]))
            })

    # Sorting: we don't have followers/repositories/joined; approximate with login ordering
    reverse = (order != "asc")
    if sort in ("followers", "repositories", "joined"):
        items.sort(key=lambda x: x.get("login") or "", reverse=reverse)

    total = len(items)
    page = items[offset: offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = base64.urlsafe_b64encode(str(next_offset).encode("utf-8")).decode("utf-8") if has_more else None

    call_row["status"] = "succeeded"
    call_row["http_status"] = 200
    call_row["response_json"] = {"total": total, "returned": len(page), "next_cursor": next_cursor}
    call_row["finished_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    call_row["updated_at"] = call_row["finished_at"]
    _save("github_tool_calls.json", calls)

    return {
        "items": page,
        "cursor": next_cursor,
        "total": total,
        "has_more": has_more,
        "meta": {"latency_ms": int((time.time() - t0) * 1000)}
    }

def get_issue(connection_id, repo_full_name, issue_number, **_extra):
    import json, os, datetime, uuid, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0069000" if __import__("os").path.isdir("./environment_mix/0069000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    def _ts():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex[:24].upper()}"

    def _log_start(conn_id, request_obj, resolved_repo_full_name=None, repo_id=None, issue_pr_id=None):
        calls = _load("github_tool_calls.json")
        call_id = _new_id("gtc")
        calls.append({
            "id": call_id,
            "connection_id": conn_id,
            "tool_name": "get_issue",
            "request_json": request_obj if isinstance(request_obj, dict) else {},
            "resolved_repo_full_name": resolved_repo_full_name,
            "repo_id": repo_id,
            "issue_pr_id": issue_pr_id,
            "http_status": None,
            "rate_limit_remaining": None,
            "rate_limit_reset_at": None,
            "status": "queued",
            "error_code": None,
            "error_message": None,
            "response_json": None,
            "started_at": None,
            "finished_at": None,
            "created_at": now,
            "updated_at": now,
        })
        _save("github_tool_calls.json", calls)
        for r in calls:
            if r.get("id") == call_id:
                r["status"] = "running"
                r["started_at"] = _ts()
                r["updated_at"] = _ts()
                break
        _save("github_tool_calls.json", calls)
        return call_id

    def _log_finish(call_id, status, http_status=None, response_json=None, error_code=None, error_message=None, resolved_repo_full_name=None, repo_id=None, issue_pr_id=None):
        calls = _load("github_tool_calls.json")
        finished = _ts()
        allowed = {"queued": {"running", "failed"}, "running": {"succeeded", "failed"}, "succeeded": set(), "failed": set()}
        for r in calls:
            if r.get("id") == call_id:
                cur = r.get("status")
                if status != cur and status not in allowed.get(cur, set()):
                    status = "failed"
                    error_code = error_code or "invalid_transition"
                    error_message = error_message or f"Invalid tool_call status transition {cur}->{status}"
                r["status"] = status
                r["http_status"] = http_status
                r["response_json"] = response_json
                r["error_code"] = error_code
                r["error_message"] = error_message
                if resolved_repo_full_name is not None:
                    r["resolved_repo_full_name"] = resolved_repo_full_name
                if repo_id is not None:
                    r["repo_id"] = repo_id
                if issue_pr_id is not None:
                    r["issue_pr_id"] = issue_pr_id
                r["finished_at"] = finished if status in ("succeeded", "failed") else r.get("finished_at")
                r["updated_at"] = finished
                break
        _save("github_tool_calls.json", calls)

    if not (isinstance(connection_id, str) and re.fullmatch(r"^ghc_[0-9A-Z]{18,}$", connection_id)):
        call_id = _log_start(connection_id if isinstance(connection_id, str) else "", {"connection_id": connection_id, "repo_full_name": repo_full_name, "issue_number": issue_number})
        _log_finish(call_id, "failed", http_status=400, error_code="validation_error", error_message="connection_id must match ^ghc_[0-9A-Z]{18,}$")
        return _err("VALIDATION_ERROR", "connection_id must match ^ghc_[0-9A-Z]{18,}$")

    if not (isinstance(repo_full_name, str) and "/" in repo_full_name and all(repo_full_name.split("/", 1))):
        call_id = _log_start(connection_id, {"connection_id": connection_id, "repo_full_name": repo_full_name, "issue_number": issue_number}, resolved_repo_full_name=repo_full_name if isinstance(repo_full_name, str) else None)
        _log_finish(call_id, "failed", http_status=400, error_code="validation_error", error_message="repo_full_name must be in owner/name form")
        return _err("VALIDATION_ERROR", "repo_full_name must be in owner/name form")

    if not (isinstance(issue_number, int) and issue_number >= 1):
        call_id = _log_start(connection_id, {"connection_id": connection_id, "repo_full_name": repo_full_name, "issue_number": issue_number}, resolved_repo_full_name=repo_full_name)
        _log_finish(call_id, "failed", http_status=400, error_code="validation_error", error_message="issue_number must be an integer >= 1")
        return _err("VALIDATION_ERROR", "issue_number must be an integer >= 1")

    call_id = _log_start(connection_id, {"connection_id": connection_id, "repo_full_name": repo_full_name, "issue_number": issue_number}, resolved_repo_full_name=repo_full_name)

    conns = _load("github_connections.json")
    conn = None
    for c in conns:
        if c.get("id") == connection_id and c.get("status") == "active":
            conn = c
            break
    if conn is None:
        _log_finish(call_id, "failed", http_status=401, error_code="github_401", error_message="Invalid or inactive connection_id.", resolved_repo_full_name=repo_full_name)
        return _err("UNAUTHORIZED", "Invalid or inactive connection_id.", connection_id=connection_id)

    repos = _load("github_repositories.json")
    repo = None
    for r in repos:
        if r.get("full_name") == repo_full_name and r.get("status") != "deleted":
            repo = r
            break
    if repo is None:
        _log_finish(call_id, "failed", http_status=404, error_code="github_404", error_message="Repository not found.", resolved_repo_full_name=repo_full_name)
        return _err("NOT_FOUND", "Repository not found.", repo_full_name=repo_full_name)

    repo_id = repo.get("id")

    issues = _load("github_issues_pull_requests.json")
    issue = None
    for it in issues:
        if it.get("repo_id") == repo_id and it.get("number") == issue_number and it.get("kind") == "issue" and it.get("status") != "deleted":
            issue = it
            break
    if issue is None:
        _log_finish(call_id, "failed", http_status=404, error_code="github_404", error_message="Issue not found.", resolved_repo_full_name=repo_full_name, repo_id=repo_id)
        return _err("NOT_FOUND", "Issue not found.", repo_full_name=repo_full_name, issue_number=issue_number)

    _log_finish(call_id, "succeeded", http_status=200, response_json={"id": issue.get("id"), "number": issue_number}, resolved_repo_full_name=repo_full_name, repo_id=repo_id, issue_pr_id=issue.get("id"))
    return {"repository": {"id": repo_id, "full_name": repo_full_name}, "issue": issue, "tool_call": {"latency_ms": int((time.time() - t0) * 1000)}}

