        _log_finish(call_id, "failed", http_status=400, error_code="validation_error", error_message="repo_full_name must be in owner/name form")
        return _err("VALIDATION_ERROR", "repo_full_name must be in owner/name form")

    if not (isinstance(pull_number, int) and pull_number >= 1):
        call_id = _log_start(connection_id, {"connection_id": connection_id, "repo_full_name": repo_full_name, "pull_number": pull_number}, resolved_repo_full_name=repo_full_name)
        _log_finish(call_id, "failed", http_status=400, error_code="validation_error", error_message="pull_number must be an integer >= 1")
        return _err("VALIDATION_ERROR", "pull_number must be an integer >= 1")

    call_id = _log_start(connection_id, {"connection_id": connection_id, "repo_full_name": repo_full_name, "pull_number": pull_number}, resolved_repo_full_name=repo_full_name)

    conns = _load("github_connections.json")
    conn = None
    for c in conns:
        if c.get("id") == connection_id and c.get("status") == "active":
            conn = c
            break
    if conn is None:
        _log_finish(call_id, "failed", http_status=401, error_code="github_401", error_message="Invalid or inactive connection_id.", resolved_repo_full_name=repo_full_name)
        return _err("UNAUTHORIZED", "Invalid or inactive connection_id.", connection_id=connection_id)

    repos = _load("github_repositories.json")
    repo = None
    for r in repos:
        if r.get("full_name") == repo_full_name and r.get("status") != "deleted":
            repo = r
            break
    if repo is None:
        _log_finish(call_id, "failed", http_status=404, error_code="github_404", error_message="Repository not found.", resolved_repo_full_name=repo_full_name)
        return _err("NOT_FOUND", "Repository not found.", repo_full_name=repo_full_name)

    repo_id = repo.get("id")

    issues = _load("github_issues_pull_requests.json")
    pr = None
    for it in issues:
        if it.get("repo_id") == repo_id and it.get("number") == pull_number and it.get("kind") == "pull_request" and it.get("status") != "deleted":
            pr = it
            break
    if pr is None:
        _log_finish(call_id, "failed", http_status=404, error_code="github_404", error_message="Pull request not found.", resolved_repo_full_name=repo_full_name, repo_id=repo_id)
        return _err("NOT_FOUND", "Pull request not found.", repo_full_name=repo_full_name, pull_number=pull_number)

    _log_finish(call_id, "succeeded", http_status=200, response_json={"id": pr.get("id"), "number": pull_number}, resolved_repo_full_name=repo_full_name, repo_id=repo_id, issue_pr_id=pr.get("id"))
    return {"repository": {"id": repo_id, "full_name": repo_full_name}, "pull_request": pr, "tool_call": {"latency_ms": int((time.time() - t0) * 1000)}}

def list_pull_requests(connection_id, repo_full_name, state=None, base=None, head=None, sort=None, direction=None, page=None, per_page=None, **_extra):
    import json, os, datetime, re, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0069000" if __import__("os").path.isdir("./environment_mix/0069000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex[:24].upper()}"

    def _parse_iso(dt):
        if not dt or not isinstance(dt, str):
            return None
        try:
            if dt.endswith("Z"):
                dt2 = dt[:-1] + "+00:00"
            else:
                dt2 = dt
            return datetime.datetime.fromisoformat(dt2)
        except Exception:
            return None

    def _tool_log_start(conn_id, request_obj, resolved_repo_full_name=None, repo_id=None, issue_pr_id=None):
        calls = _load("github_tool_calls.json")
        call_id = _new_id("gtc")
        row = {
            "id": call_id,
            "connection_id": conn_id,
            "tool_name": "list_pull_requests",
            "request_json": request_obj if isinstance(request_obj, dict) else {},
            "resolved_repo_full_name": resolved_repo_full_name,
            "repo_id": repo_id,
            "issue_pr_id": issue_pr_id,
            "http_status": None,
            "rate_limit_remaining": None,
            "rate_limit_reset_at": None,
            "status": "queued",
            "error_code": None,
            "error_message": None,
            "response_json": None,
            "started_at": None,
            "finished_at": None,
            "created_at": now,
            "updated_at": now,
        }
        calls.append(row)
        _save("github_tool_calls.json", calls)
        for r in calls:
            if r.get("id") == call_id:
                r["status"] = "running"
                r["started_at"] = now
                r["updated_at"] = now
                break
        _save("github_tool_calls.json", calls)
        return call_id

    def _tool_log_finish(call_id, status, http_status=None, response_json=None, error_code=None, error_message=None):
        calls = _load("github_tool_calls.json")
        finished = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        for r in calls:
            if r.get("id") == call_id:
                cur = r.get("status")
                allowed = {"queued": {"running", "failed"}, "running": {"succeeded", "failed"}, "succeeded": set(), "failed": set()}
                if status not in allowed.get(cur, set()):
                    status = "failed"
                    error_code = error_code or "invalid_transition"
                    error_message = error_message or f"Illegal tool call transition {cur}->{status}"
                    http_status = http_status or 500
                r["status"] = status
                r["http_status"] = http_status
                r["response_json"] = response_json
                r["error_code"] = error_code
                r["error_message"] = error_message
                r["finished_at"] = finished
                r["updated_at"] = finished
                break
        _save("github_tool_calls.json", calls)

    # Validate
    if not isinstance(connection_id, str) or not re.match(r"^ghc_[0-9A-Z]{18,}$", connection_id):
        return _err("VALIDATION_ERROR", "connection_id is invalid; expected ^ghc_[0-9A-Z]{18,}$")
    if not isinstance(repo_full_name, str) or "/" not in repo_full_name:
        return _err("VALIDATION_ERROR", "repo_full_name must be in owner/name format")
    owner, name = repo_full_name.split("/", 1)
    if not owner or not name or " " in owner or " " in name or repo_full_name.count("/") != 1:
        return _err("VALIDATION_ERROR", "repo_full_name must be in owner/name format")

    if state is not None:
        if not isinstance(state, str) or state not in ("open", "closed", "all"):
            return _err("VALIDATION_ERROR", "state must be one of: open, closed, all")
    if sort is not None:
        if not isinstance(sort, str) or sort not in ("created", "updated", "popularity", "long-running"):
            return _err("VALIDATION_ERROR", "sort must be one of: created, updated, popularity, long-running")
    if direction is not None:
        if not isinstance(direction, str) or direction not in ("asc", "desc"):
            return _err("VALIDATION_ERROR", "direction must be one of: asc, desc")
    if base is not None and not isinstance(base, str):
        return _err("VALIDATION_ERROR", "base must be a string")
    if head is not None and not isinstance(head, str):
        return _err("VALIDATION_ERROR", "head must be a string")

    if page is None:
        page = 1
    if per_page is None:
        per_page = 30
    if not isinstance(page, int) or page < 1:
        return _err("VALIDATION_ERROR", "page must be an integer >= 1")
    if not isinstance(per_page, int) or per_page < 1 or per_page > 100:
        return _err("VALIDATION_ERROR", "per_page must be an integer between 1 and 100")

    # Auth connection
    conns = _load("github_connections.json")
    conn = next((c for c in conns if c.get("id") == connection_id), None)
    if not conn:
        return _err("UNAUTHORIZED", "Connection not found or not authorized")
    if conn.get("status") != "active":
        call_id = _tool_log_start(connection_id, {"connection_id": connection_id, "repo_full_name": repo_full_name, "state": state, "base": base, "head": head, "sort": sort, "direction": direction, "page": page, "per_page": per_page}, resolved_repo_full_name=repo_full_name)
        _tool_log_finish(call_id, "failed", http_status=401, error_code="github_401", error_message="Connection is not active")
        return _err("UNAUTHORIZED", "Connection is not active")

    repos = _load("github_repositories.json")
    repo = next((r for r in repos if r.get("full_name") == repo_full_name), None)

    call_id = _tool_log_start(connection_id, {"connection_id": connection_id, "repo_full_name": repo_full_name, "state": state, "base": base, "head": head, "sort": sort, "direction": direction, "page": page, "per_page": per_page}, resolved_repo_full_name=repo_full_name, repo_id=(repo.get("id") if repo else None))

    if not repo:
        _tool_log_finish(call_id, "failed", http_status=404, error_code="github_404", error_message="Repository not found")
        return _err("NOT_FOUND", "Repository not found")
    if repo.get("status") in ("deleted", "access_revoked"):
        _tool_log_finish(call_id, "failed", http_status=404, error_code="github_404", error_message="Repository not accessible")
        return _err("NOT_FOUND", "Repository not accessible")
    if repo.get("connection_id") != connection_id:
        _tool_log_finish(call_id, "failed", http_status=401, error_code="github_401", error_message="Connection cannot access repository")
        return _err("UNAUTHORIZED", "Connection cannot access repository")

    items = _load("github_issues_pull_requests.json")
    prs = [i for i in items if i.get("repo_id") == repo.get("id") and i.get("kind") == "pull_request" and i.get("status") not in ("deleted", "access_revoked")]

    # Filters
    if state and state != "all":
        prs = [p for p in prs if p.get("state") == state]
    if base is not None:
        prs = [p for p in prs if p.get("base_branch") == base]
    if head is not None:
        # head can be "branch" or "owner:branch" (we store just head_branch plus optional head_repo_full_name)
        if ":" in head:
            h_owner, h_branch = head.split(":", 1)
            def _matches(p):
                hr = p.get("head_repo_full_name")
                if hr and "/" in hr:
                    return hr.split("/", 1)[0] == h_owner and p.get("head_branch") == h_branch
                return False
            prs = [p for p in prs if _matches(p)]
        else:
            prs = [p for p in prs if p.get("head_branch") == head]

    # Sorting
    if not sort:
        sort = "created"
    if not direction:
        direction = "desc"
    reverse = (direction == "desc")

    def _sort_key(p):
        if sort == "updated":
            return _parse_iso(p.get("github_updated_at")) or _parse_iso(p.get("updated_at")) or datetime.datetime.min
        if sort == "created":
            return _parse_iso(p.get("created_at")) or datetime.datetime.min
        if sort == "popularity":
            # not tracked; stable fallback to number
            return p.get("number") or 0
        if sort == "long-running":
            # open oldest first/last depending on direction; approximate by created_at
            return _parse_iso(p.get("created_at")) or datetime.datetime.min
        return _parse_iso(p.get("created_at")) or datetime.datetime.min

    prs_sorted = sorted(prs, key=_sort_key, reverse=reverse)

    total = len(prs_sorted)
    start = (page - 1) * per_page
    end = start + per_page
    page_items = prs_sorted[start:end]
    has_more = end < total

    _tool_log_finish(call_id, "succeeded", http_status=200, response_json={"total": total, "count": len(page_items)})

    return {
        "pull_requests": page_items,
        "repo": {"id": repo.get("id"), "full_name": repo.get("full_name")},
        "page": page,
        "per_page": per_page,
        "total": total,
        "has_more": has_more,
        "meta": {"latency_ms": int((time.time() - t0) * 1000)}
    }

def get_pull_request_files(connection_id, repo_full_name, pull_number, page=None, per_page=None, **_extra):
    import json, os, datetime, re, time, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0069000" if __import__("os").path.isdir("./environment_mix/0069000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # Validate
    if not isinstance(connection_id, str) or not re.match(r"^ghc_[0-9A-Z]{18,}$", connection_id):
        return _err("VALIDATION_ERROR", "connection_id is invalid.")
    if not isinstance(repo_full_name, str) or not re.match(r"^[A-Za-z0-9_.-]+/[A-Za-z0-9_.-]+$", repo_full_name):
        return _err("VALIDATION_ERROR", "repo_full_name must be in owner/name form.")
    if not isinstance(pull_number, int) or pull_number < 1:
        return _err("VALIDATION_ERROR", "pull_number must be an integer >= 1.")
    if page is None:
        page = 1
    if per_page is None:
        per_page = 30
    if not isinstance(page, int) or page < 1:
        return _err("VALIDATION_ERROR", "page must be an integer >= 1.")
    if not isinstance(per_page, int) or per_page < 1 or per_page > 100:
        return _err("VALIDATION_ERROR", "per_page must be an integer in 1-100.")

    connections = _load("github_connections.json")
    repos = _load("github_repositories.json")
    issues_prs = _load("github_issues_pull_requests.json")
    artifacts = _load("github_discussion_artifacts.json")
    tool_calls = _load("github_tool_calls.json")

    conn = next((c for c in connections if c.get("id") == connection_id), None)
    if not conn or conn.get("status") != "active":
        return _err("UNAUTHORIZED", "No active GitHub connection available for this request.")

    repo = next((r for r in repos if r.get("full_name") == repo_full_name), None)
    if not repo:
        return _err("NOT_FOUND", "Repository not found.", repo_full_name=repo_full_name)
    repo_id = repo.get("id")

    pr = next((x for x in issues_prs if x.get("repo_id") == repo_id and x.get("number") == pull_number and x.get("kind") == "pull_request"), None)
    if not pr:
        return _err("NOT_FOUND", "Pull request not found.", repo_full_name=repo_full_name, pull_number=pull_number)
    issue_pr_id = pr.get("id")

    # Tool call bookkeeping: queued then running then succeeded
    tc_id = "ghtc_" + secrets.token_hex(12)
    tc = {
        "id": tc_id,
        "connection_id": conn["id"],
        "tool_name": "get_pull_request_files",
        "request_json": {
            "connection_id": connection_id,
            "repo_full_name": repo_full_name,
            "pull_number": pull_number,
            "page": page,
            "per_page": per_page
        },
        "resolved_repo_full_name": repo_full_name,
        "repo_id": repo_id,
        "issue_pr_id": issue_pr_id,
        "http_status": None,
        "rate_limit_remaining": None,
        "rate_limit_reset_at": None,
        "status": "queued",
        "error_code": None,
        "error_message": None,
        "response_json": None,
        "started_at": None,
        "finished_at": None,
        "created_at": now,
        "updated_at": now
    }
    tool_calls.append(tc)
    _save("github_tool_calls.json", tool_calls)

    tc["status"] = "running"
    tc["started_at"] = now
    tc["updated_at"] = now
    _save("github_tool_calls.json", tool_calls)

    try:
        # Read/write artifact_type='pr_changed_file' keyed by (issue_pr_id, path)
        rows = [a for a in artifacts if a.get("issue_pr_id") == issue_pr_id and a.get("artifact_type") == "pr_changed_file" and a.get("status") != "deleted"]

        # If none exist, treat as cache miss; do not fabricate. Return empty set but succeed.
        # (Business rule says read/write; without external GitHub we can't fetch.)
        # Pagination
        rows.sort(key=lambda x: (x.get("path") or "", x.get("github_id") or 0, x.get("id") or ""))
        total = len(rows)
        start = (page - 1) * per_page
        end = start + per_page
        page_items = rows[start:end]
        has_more = end < total

        resp = {
            "files": [
                {
                    "path": r.get("path"),
                    "file_status": r.get("file_status"),
                    "additions": r.get("additions"),
                    "deletions": r.get("deletions"),
                    "changes": r.get("changes"),
                    "github_id": r.get("github_id"),
                    "status": r.get("status"),
                    "github_created_at": r.get("github_created_at"),
                    "github_updated_at": r.get("github_updated_at")
                }
                for r in page_items
            ],
            "pagination": {
                "page": page,
                "per_page": per_page,
                "total": total,
                "has_more": has_more
            }
        }

        tc["status"] = "succeeded"
        tc["http_status"] = 200
        tc["response_json"] = {"count": len(page_items), "total": total, "page": page, "per_page": per_page}
        tc["finished_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        tc["updated_at"] = tc["finished_at"]
        _save("github_tool_calls.json", tool_calls)

        return {
            "repo_full_name": repo_full_name,
            "pull_number": pull_number,
            **resp,
            "tool_call": {"id": tc_id, "status": tc["status"], "http_status": tc["http_status"]}
        }
    except Exception as e:
        tc["status"] = "failed"
        tc["http_status"] = 500
        tc["error_code"] = "internal_error"
        tc["error_message"] = str(e)
        tc["response_json"] = None
        tc["finished_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        tc["updated_at"] = tc["finished_at"]
        _save("github_tool_calls.json", tool_calls)
        return _err("CONFLICT", "Internal error while listing pull request files.", detail=str(e))

def add_pull_request_comment(repo_full_name, pull_number, body, commit_id, path, side=None, line=None, start_line=None, start_side=None, **_extra):
    import json, os, datetime, uuid, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0069000" if __import__("os").path.isdir("./environment_mix/0069000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    def _ts():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex[:24].upper()}"
    def _is_sha(s):
        return isinstance(s, str) and re.fullmatch(r"[0-9a-f]{7,40}", s) is not None

    # Ambient auth: choose connection via repo.connection_id else any active
    repos = _load("github_repositories.json")
    repo = None
    for r in repos:
        if r.get("full_name") == repo_full_name and r.get("status") != "deleted":
            repo = r
            break

    conns = _load("github_connections.json")
    conn_id = None
    pref = repo.get("connection_id") if repo else None
    if isinstance(pref, str):
        for c in conns:
            if c.get("id") == pref and c.get("status") == "active":
                conn_id = pref
                break
    if conn_id is None:
        for c in conns:
            if c.get("status") == "active":
                conn_id = c.get("id")
                break

    # Log queued->running
    calls = _load("github_tool_calls.json")
    call_id = _new_id("gtc")
    calls.append({
        "id": call_id,
        "connection_id": conn_id or "",
        "tool_name": "add_pull_request_comment",
        "request_json": {"repo_full_name": repo_full_name, "pull_number": pull_number, "body": body, "commit_id": commit_id, "path": path, "side": side, "line": line, "start_line": start_line, "start_side": start_side},
        "resolved_repo_full_name": repo_full_name,
        "repo_id": repo.get("id") if repo else None,
        "issue_pr_id": None,
        "http_status": None,
        "rate_limit_remaining": None,
        "rate_limit_reset_at": None,
        "status": "queued",
        "error_code": None,
        "error_message": None,
        "response_json": None,
        "started_at": None,
        "finished_at": None,
        "created_at": now,
        "updated_at": now,
    })
    _save("github_tool_calls.json", calls)
    for r in calls:
        if r.get("id") == call_id:
            r["status"] = "running"
            r["started_at"] = _ts()
            r["updated_at"] = _ts()
            break
    _save("github_tool_calls.json", calls)

    # Validate
    if not (isinstance(repo_full_name, str) and "/" in repo_full_name and all(repo_full_name.split("/", 1))):
        for r in calls:
            if r.get("id") == call_id:
                r["status"] = "failed"; r["http_status"] = 400
                r["error_code"] = "validation_error"; r["error_message"] = "repo_full_name must be in owner/name form"
                r["finished_at"] = _ts(); r["updated_at"] = _ts()
                break
        _save("github_tool_calls.json", calls)
        return _err("VALIDATION_ERROR", "repo_full_name must be in owner/name form")

    if not (isinstance(pull_number, int) and pull_number >= 1):
        for r in calls:
            if r.get("id") == call_id:
                r["status"] = "failed"; r["http_status"] = 400
                r["error_code"] = "validation_error"; r["error_message"] = "pull_number must be an integer >= 1"
                r["finished_at"] = _ts(); r["updated_at"] = _ts()
                break
        _save("github_tool_calls.json", calls)
        return _err("VALIDATION_ERROR", "pull_number must be an integer >= 1")

    if not (isinstance(body, str) and body.strip() != ""):
        for r in calls:
            if r.get("id") == call_id:
                r["status"] = "failed"; r["http_status"] = 400
                r["error_code"] = "validation_error"; r["error_message"] = "body must be a non-empty string"
                r["finished_at"] = _ts(); r["updated_at"] = _ts()
                break
        _save("github_tool_calls.json", calls)
        return _err("VALIDATION_ERROR", "body must be a non-empty string")

    if not _is_sha(commit_id):
        for r in calls:
            if r.get("id") == call_id:
                r["status"] = "failed"; r["http_status"] = 400
                r["error_code"] = "validation_error"; r["error_message"] = "commit_id must be a git SHA (7-40 lowercase hex)."
                r["finished_at"] = _ts(); r["updated_at"] = _ts()
                break
        _save("github_tool_calls.json", calls)
        return _err("VALIDATION_ERROR", "commit_id must be a git SHA (7-40 lowercase hex).")

    if not (isinstance(path, str) and path.strip() != ""):
        for r in calls:
            if r.get("id") == call_id:
                r["status"] = "failed"; r["http_status"] = 400
                r["error_code"] = "validation_error"; r["error_message"] = "path must be a non-empty string"
                r["finished_at"] = _ts(); r["updated_at"] = _ts()
                break
        _save("github_tool_calls.json", calls)
        return _err("VALIDATION_ERROR", "path must be a non-empty string")

    if side is not None and side not in ("LEFT", "RIGHT"):
        for r in calls:
            if r.get("id") == call_id:
                r["status"] = "failed"; r["http_status"] = 400
                r["error_code"] = "validation_error"; r["error_message"] = "side must be LEFT or RIGHT when provided"
                r["finished_at"] = _ts(); r["updated_at"] = _ts()
                break
        _save("github_tool_calls.json", calls)
        return _err("VALIDATION_ERROR", "side must be LEFT or RIGHT when provided")

    if start_side is not None and start_side not in ("LEFT", "RIGHT"):
        for r in calls:
            if r.get("id") == call_id:
                r["status"] = "failed"; r["http_status"] = 400
                r["error_code"] = "validation_error"; r["error_message"] = "start_side must be LEFT or RIGHT when provided"
                r["finished_at"] = _ts(); r["updated_at"] = _ts()
                break
        _save("github_tool_calls.json", calls)
        return _err("VALIDATION_ERROR", "start_side must be LEFT or RIGHT when provided")

    # Must have line or position per business rules; this endpoint provides line/start_line, so enforce line.
    if not (isinstance(line, int) and line >= 1):
        for r in calls:
            if r.get("id") == call_id:
                r["status"] = "failed"; r["http_status"] = 400
                r["error_code"] = "validation_error"; r["error_message"] = "line (>=1) is required for pull request review comments."
                r["finished_at"] = _ts(); r["updated_at"] = _ts()
                break
        _save("github_tool_calls.json", calls)
        return _err("VALIDATION_ERROR", "line (>=1) is required for pull request review comments.")

    # Multi-line consistency: if start_line provided, must be < line and start_side provided; if start_side provided, must have start_line.
    if start_line is not None:
        if not (isinstance(start_line, int) and start_line >= 1 and start_line <= line):
            for r in calls:
                if r.get("id") == call_id:
                    r["status"] = "failed"; r["http_status"] = 400
                    r["error_code"] = "validation_error"; r["error_message"] = "start_line must be an integer >=1 and <= line."
                    r["finished_at"] = _ts(); r["updated_at"] = _ts()
                    break
            _save("github_tool_calls.json", calls)
            return _err("VALIDATION_ERROR", "start_line must be an integer >=1 and <= line.")
        if start_side is None:
            for r in calls:
                if r.get("id") == call_id:
                    r["status"] = "failed"; r["http_status"] = 400
                    r["error_code"] = "validation_error"; r["error_message"] = "start_side is required when start_line is provided."
                    r["finished_at"] = _ts(); r["updated_at"] = _ts()
                    break
            _save("github_tool_calls.json", calls)
            return _err("VALIDATION_ERROR", "start_side is required when start_line is provided.")
    if start_side is not None and start_line is None:
        for r in calls:
            if r.get("id") == call_id:
                r["status"] = "failed"; r["http_status"] = 400
                r["error_code"] = "validation_error"; r["error_message"] = "start_line is required when start_side is provided."
                r["finished_at"] = _ts(); r["updated_at"] = _ts()
                break
        _save("github_tool_calls.json", calls)
        return _err("VALIDATION_ERROR", "start_line is required when start_side is provided.")

    if repo is None:
        for r in calls:
            if r.get("id") == call_id:
                r["status"] = "failed"; r["http_status"] = 404
                r["error_code"] = "github_404"; r["error_message"] = "Repository not found."
                r["finished_at"] = _ts(); r["updated_at"] = _ts()
                break
        _save("github_tool_calls.json", calls)
        return _err("NOT_FOUND", "Repository not found.", repo_full_name=repo_full_name)
    if conn_id is None:
        for r in calls:
            if r.get("id") == call_id:
                r["status"] = "failed"; r["http_status"] = 401
                r["error_code"] = "github_401"; r["error_message"] = "No active connection available."
                r["finished_at"] = _ts(); r["updated_at"] = _ts()
                break
        _save("github_tool_calls.json", calls)
        return _err("UNAUTHORIZED", "No active connection available.")

    repo_id = repo.get("id")
    items = _load("github_issues_pull_requests.json")
    pr = None
    for it in items:
        if it.get("repo_id") == repo_id and it.get("number") == pull_number and it.get("kind") == "pull_request" and it.get("status") != "deleted":
            pr = it
            break
    if pr is None:
        for r in calls:
            if r.get("id") == call_id:
                r["status"] = "failed"; r["http_status"] = 404
                r["error_code"] = "github_404"; r["error_message"] = "Pull request not found."
                r["finished_at"] = _ts(); r["updated_at"] = _ts()
                break
        _save("github_tool_calls.json", calls)
        return _err("NOT_FOUND", "Pull request not found.", repo_full_name=repo_full_name, pull_number=pull_number)

    issue_pr_id = pr.get("id")

    artifacts = _load("github_discussion_artifacts.json")
    max_gid = 0
    for a in artifacts:
        gid = a.get("github_id")
        if isinstance(gid, int) and gid > max_gid:
            max_gid = gid
    github_id = max_gid + 1

    comment = {
        "id": _new_id("ghd"),
        "repo_id": repo_id,
        "issue_pr_id": issue_pr_id,
        "artifact_type": "pr_review_comment",
        "github_id": github_id,
        "author_login": None,
        "body": body,
        "in_reply_to_github_id": None,
        "path": path,
        "position": None,
        "line": line,
        "side": side or "RIGHT",
        "commit_sha": commit_id,
        "diff_hunk": None,
        "review_state": None,
        "thread_resolved": None,
        "file_status": None,
        "additions": None,
        "deletions": None,
        "changes": None,
        "status_rollup": None,
        "status": "active",
        "github_created_at": _ts(),
        "github_updated_at": _ts(),
        "created_at": _ts(),
        "updated_at": _ts(),
    }
    artifacts.append(comment)
    _save("github_discussion_artifacts.json", artifacts)

    for r in calls:
        if r.get("id") == call_id:
            r["status"] = "succeeded"
            r["http_status"] = 201
            r["repo_id"] = repo_id
            r["issue_pr_id"] = issue_pr_id
            r["response_json"] = {"id": comment["id"], "github_id": github_id, "artifact_type": "pr_review_comment", "path": path, "line": line}
            r["finished_at"] = _ts()
            r["updated_at"] = _ts()
            break
    _save("github_tool_calls.json", calls)

    return {
        "repository": {"id": repo_id, "full_name": repo_full_name},
        "pull_request": {"id": issue_pr_id, "number": pull_number},
        "comment": {"id": comment["id"], "github_id": github_id, "path": path, "line": line, "side": comment["side"], "commit_id": commit_id, "body": body},
        "tool_call": {"latency_ms": int((time.time() - t0) * 1000)},
    }

def list_repositories(connection_id=None, owner_login=None, query=None, visibility=None, is_fork=None, archived=None, disabled=None, status=None, page=None, per_page=None, sort=None, order=None, **_extra):
    import json, os, datetime, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0069000" if __import__("os").path.isdir("./environment_mix/0069000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # Validate filters/pagination
    if connection_id is not None:
        if not isinstance(connection_id, str) or not re.match(r"^ghc_[0-9A-Z]{18,}$", connection_id):
            return _err("VALIDATION_ERROR", "Invalid connection_id.", field="connection_id")
    if owner_login is not None and not isinstance(owner_login, str):
        return _err("VALIDATION_ERROR", "owner_login must be a string.", field="owner_login")
    if query is not None and not isinstance(query, str):
        return _err("VALIDATION_ERROR", "query must be a string.", field="query")
    if visibility is not None and visibility not in ("public", "private", "internal"):
        return _err("VALIDATION_ERROR", "Invalid visibility.", field="visibility")
    for bname, bval in (("is_fork", is_fork), ("archived", archived), ("disabled", disabled)):
        if bval is not None and not isinstance(bval, bool):
            return _err("VALIDATION_ERROR", f"{bname} must be boolean.", field=bname)
    if status is not None and status not in ("active", "pending_fork", "deleted", "access_revoked"):
        return _err("VALIDATION_ERROR", "Invalid status.", field="status")
    if page is None:
        page = 1
    if per_page is None:
        per_page = 30
    if not isinstance(page, int) or page < 1:
        return _err("VALIDATION_ERROR", "Invalid page; must be integer >= 1.", field="page")
    if not isinstance(per_page, int) or per_page < 1 or per_page > 100:
        return _err("VALIDATION_ERROR", "Invalid per_page; must be integer 1..100.", field="per_page")
    if sort is None:
        sort = "updated_at"
    if sort not in ("pushed_at", "updated_at", "created_at", "full_name"):
        return _err("VALIDATION_ERROR", "Invalid sort.", field="sort")
    if order is None:
        order = "desc"
    if order not in ("asc", "desc"):
        return _err("VALIDATION_ERROR", "Invalid order.", field="order")

    conns = _load("github_connections.json")
    repos = _load("github_repositories.json")
    calls = _load("github_tool_calls.json")

    # Create tool_call row (required)
    try:
        call_id = "ghtc_" + os.urandom(12).hex()
    except Exception:
        call_id = "ghtc_" + str(int(time.time() * 1000))

    # Resolve a usable connection context.
    resolved_conn = None
    if connection_id is not None:
        c = next((c for c in conns if c.get("id") == connection_id), None)
        if c is None or c.get("status") == "revoked":
            # log failed
            tool_call = {
                "id": call_id,
                "connection_id": connection_id,
                "tool_name": "list_repositories",
                "request_json": {
                    "connection_id": connection_id, "owner_login": owner_login, "query": query, "visibility": visibility,
                    "is_fork": is_fork, "archived": archived, "disabled": disabled, "status": status,
                    "page": page, "per_page": per_page, "sort": sort, "order": order
                },
                "resolved_repo_full_name": None,
                "repo_id": None,
                "issue_pr_id": None,
                "http_status": 401,
                "rate_limit_remaining": None,
                "rate_limit_reset_at": None,
                "status": "failed",
                "error_code": "github_401",
                "error_message": "Connection is unknown or revoked.",
                "response_json": None,
                "started_at": now,
                "finished_at": now,
                "created_at": now,
                "updated_at": now,
            }
            calls.append(tool_call)
            _save("github_tool_calls.json", calls)
            return _err("UNAUTHORIZED", "Connection cannot be used.", connection_id=connection_id)
        if c.get("status") == "error":
            tool_call = {
                "id": call_id,
                "connection_id": connection_id,
                "tool_name": "list_repositories",
                "request_json": {
                    "connection_id": connection_id, "owner_login": owner_login, "query": query, "visibility": visibility,
                    "is_fork": is_fork, "archived": archived, "disabled": disabled, "status": status,
                    "page": page, "per_page": per_page, "sort": sort, "order": order
                },
                "resolved_repo_full_name": None,
                "repo_id": None,
                "issue_pr_id": None,
                "http_status": 412,
                "rate_limit_remaining": None,
                "rate_limit_reset_at": None,
                "status": "failed",
                "error_code": "failed_precondition",
                "error_message": "Connection is in error state.",
                "response_json": None,
                "started_at": now,
                "finished_at": now,
                "created_at": now,
                "updated_at": now,
            }
            calls.append(tool_call)
            _save("github_tool_calls.json", calls)
            return _err("INVALID_TRANSITION", "Connection is in error state and cannot be used.", connection_id=connection_id)
        resolved_conn = c
    else:
        # Ambient auth: pick any usable connection if any exist; else allow listing cached repos without a connection?
        # Spec: "when omitted, returns cached repositories across connections the caller can access."
        # Without an explicit auth param, caller is authenticated; find at least one active connection as accessible context.
        resolved_conn = next((c for c in conns if c.get("status") == "active"), None)
        if resolved_conn is None:
            # If there are cached repos but no active connection, treat as unauthorized (caller cannot access any).
            tool_call = {
                "id": call_id,
                "connection_id": None,
                "tool_name": "list_repositories",
                "request_json": {
                    "connection_id": None, "owner_login": owner_login, "query": query, "visibility": visibility,
                    "is_fork": is_fork, "archived": archived, "disabled": disabled, "status": status,
                    "page": page, "per_page": per_page, "sort": sort, "order": order
                },
                "resolved_repo_full_name": None,
                "repo_id": None,
                "issue_pr_id": None,
                "http_status": 401,
                "rate_limit_remaining": None,
                "rate_limit_reset_at": None,
                "status": "failed",
                "error_code": "github_401",
                "error_message": "No usable connection available.",
                "response_json": None,
                "started_at": now,
                "finished_at": now,
                "created_at": now,
                "updated_at": now,
            }
            calls.append(tool_call)
            _save("github_tool_calls.json", calls)
            return _err("UNAUTHORIZED", "No usable connection available.")

    # Insert tool call queued then running
    tool_call = {
        "id": call_id,
        "connection_id": resolved_conn.get("id") if resolved_conn else (connection_id if connection_id is not None else None),
        "tool_name": "list_repositories",
        "request_json": {
            "connection_id": connection_id, "owner_login": owner_login, "query": query, "visibility": visibility,
            "is_fork": is_fork, "archived": archived, "disabled": disabled, "status": status,
            "page": page, "per_page": per_page, "sort": sort, "order": order
        },
        "resolved_repo_full_name": None,
        "repo_id": None,
        "issue_pr_id": None,
        "http_status": None,
        "rate_limit_remaining": None,
        "rate_limit_reset_at": None,
        "status": "queued",
        "error_code": None,
        "error_message": None,
        "response_json": None,
        "started_at": None,
        "finished_at": None,
        "created_at": now,
        "updated_at": now,
    }
    calls.append(tool_call)
    _save("github_tool_calls.json", calls)
    tool_call["status"] = "running"
    tool_call["started_at"] = now
    tool_call["updated_at"] = now
    _save("github_tool_calls.json", calls)

    # Apply filters to cached repos
    rows = repos

    if connection_id is not None:
        rows = [r for r in rows if r.get("connection_id") == connection_id]
    # else: across accessible connections — we don't have per-caller ACLs in schema; treat all repos as visible.

    if owner_login is not None:
        rows = [r for r in rows if isinstance(r.get("owner_login"), str) and r.get("owner_login") == owner_login]
    if visibility is not None:
        rows = [r for r in rows if r.get("visibility") == visibility]
    if is_fork is not None:
        rows = [r for r in rows if r.get("is_fork") is is_fork]
    if archived is not None:
        rows = [r for r in rows if r.get("archived") is archived]
    if disabled is not None:
        rows = [r for r in rows if r.get("disabled") is disabled]
    if status is not None:
        rows = [r for r in rows if r.get("status") == status]
    if query is not None:
        q = query.casefold()
        def _match(r):
            fn = (r.get("full_name") or "")
            nm = (r.get("name") or "")
            return q in fn.casefold() or q in nm.casefold()
        rows = [r for r in rows if _match(r)]

    total = len(rows)

    # Sorting
    def _dt_key(v):
        if not v:
            return ""
        return v
    if sort in ("pushed_at", "updated_at", "created_at"):
        rows.sort(key=lambda r: _dt_key(r.get(sort)), reverse=(order == "desc"))
    elif sort == "full_name":
        rows.sort(key=lambda r: (r.get("full_name") or "").casefold(), reverse=(order == "desc"))

    # Pagination (page-based)
    start = (page - 1) * per_page
    end = start + per_page
    page_rows = rows[start:end]
    has_more = end < total

    resp = {
        "repositories": page_rows,
        "page": page,
        "per_page": per_page,
        "total": total,
        "has_more": has_more,
    }

    tool_call["status"] = "succeeded"
    tool_call["http_status"] = 200
    tool_call["response_json"] = {"count": len(page_rows), "total": total, "page": page, "per_page": per_page}
    tool_call["finished_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    tool_call["updated_at"] = tool_call["finished_at"]
    _save("github_tool_calls.json", calls)

    resp["meta"] = {"tool_call_id": call_id, "latency_ms": int((time.time() - t0) * 1000)}
    return resp
